func:
// WebSocket /ws/live: หน้าเว็บส่ง {type:"auth", token, farm_id} มาก่อน ถึงจะได้รับข้อมูลสด
// ผู้ที่ไม่ใช่ admin ได้รับเฉพาะฟาร์มของตัวเองเสมอ ไม่ว่าจะขอฟาร์มไหน
const scf = global.get("scf");
const sid = msg._session && msg._session.id;
if (!sid || typeof msg.payload !== "string" || msg.payload.length > 2048) return null;
let m;
try { m = JSON.parse(msg.payload); } catch (e) { return null; }
const reply = obj => ({ _session: msg._session, payload: JSON.stringify(obj) });
if (m.type === "ping") return reply({ type: "pong" });
if (m.type !== "auth") return null;

const p = scf.verifyToken(m.token);
const u = p && (global.get("users") || {})[p.uid];
if (!p || !u || !u.active || (u.session_version || 0) !== p.sv) return reply({ type: "auth-failed" });
const farmId = u.role === "admin" ? scf.int(m.farm_id) : u.farm_id;
const sessions = global.get("wsSessions") || {};
const now = Date.now() / 1000;
for (const [k, s] of Object.entries(sessions)) if (s.exp < now) delete sessions[k];
const ids = Object.keys(sessions);
if (ids.length > 1000) ids.sort((a, b) => sessions[a].at - sessions[b].at).slice(0, ids.length - 1000).forEach(k => delete sessions[k]);
sessions[sid] = { uid: u.id, sv: p.sv, exp: p.exp, farm_id: farmId, at: Date.now() };
global.set("wsSessions", sessions);
node.status({ fill: "green", shape: "dot", text: Object.keys(sessions).length + " หน้าจอ" });
return reply({ type: "ready", farm_id: farmId });

// ส่งข้อมูลสดให้เฉพาะหน้าจอของคนในฟาร์มนั้น   msg.payload = {farm_id (null = ทุกคน), data}
// ตรวจสิทธิ์ซ้ำทุกครั้ง: บัญชีถูกปิด/เปลี่ยนสิทธิ์/token หมดอายุ -> ตัดการรับข้อมูลทันที
const sessions = global.get("wsSessions") || {}, users = global.get("users") || {};
const { farm_id, data } = msg.payload || {};
if (!data) return null;
const text = JSON.stringify(data), now = Date.now() / 1000, out = [];
for (const [sid, s] of Object.entries(sessions)) {
    const u = users[s.uid];
    if (!u || !u.active || (u.session_version || 0) !== s.sv || s.exp < now) {
        out.push({ _session: { type: "websocket", id: sid }, payload: JSON.stringify({ type: "auth-expired" }) });
        delete sessions[sid];
        continue;
    }
    if (farm_id != null && s.farm_id !== farm_id) continue;
    if (u.role === "coop_keeper" && farm_id != null) {       // ผู้ดูแลโรงเรือน: เฉพาะโรงเรือนของตัวเอง
        if (data.coop_id != null ? !(u.coop_ids || []).includes(Number(data.coop_id)) : data.type === "alert") continue;
    }
    out.push({ _session: { type: "websocket", id: sid }, payload: text });
}
global.set("wsSessions", sessions);
return [out];

// ตั้งเวลาไฟ: โรงเรือนโหมด "ตั้งเวลา" ให้ไฟติดในช่วง light_on -> light_off (ข้ามเที่ยงคืนได้) ทุกฟาร์ม
const now = new Date(), mins = now.getHours() * 60 + now.getMinutes();
const toMin = s => { const p = String(s).split(":").map(Number); return p[0] * 60 + p[1]; };
const out = [];
let auto = 0;
for (const c of global.get("coops") || []) {
    if (!c.active || c.light_mode !== "auto" || !c.mqtt_user) continue;
    auto++;
    const on = toMin(c.light_on), off = toMin(c.light_off);
    const want = on === off ? true : on < off ? (mins >= on && mins < off) : (mins >= on || mins < off);
    if (flow.get("set_" + c.id) === want) continue;
    flow.set("set_" + c.id, want);
    out.push({ topic: "scf/" + c.mqtt_user + "/node/" + c.node_id + "/light/set", payload: want ? "ON" : "OFF", retain: true, qos: 1 });
}
node.status(auto ? { fill: "blue", shape: "dot", text: auto + " โรงเรือนตั้งเวลา" } : { fill: "grey", shape: "ring", text: "ไม่มีโรงเรือนตั้งเวลา" });
return [out];

// INSERT INTO readings
const scf = global.get("scf");
const r = msg.reading;
try {
    await scf.db.insert("readings", { coop_id: r.coop_id, temp: r.temp, humidity: r.humidity });
    node.status({ fill: "green", shape: "dot", text: "บันทึกล่าสุด " + new Date().toLocaleTimeString("th-TH") });
} catch (e) {
    node.status({ fill: "red", shape: "ring", text: e.message.slice(0, 40) });
    node.error("บันทึกค่าไม่สำเร็จ: " + e.message);
}
return null;

// เก็บการแจ้งเตือนลงตาราง alerts แล้วส่งให้หน้าจอของคนในฟาร์มนั้น
const scf = global.get("scf");
const a = msg.alert;
let at = new Date().toISOString();
try {
    const rows = await scf.db.insert("alerts", { farm_id: a.farm_id, coop_id: a.coop_id, level: a.level, message: a.message, temp: a.temp, humidity: a.humidity });
    if (rows && rows[0]) at = rows[0].created_at;
} catch (e) { node.error("บันทึกการแจ้งเตือนไม่สำเร็จ: " + e.message); }
node.status({ fill: a.level === "ok" ? "green" : "red", shape: "dot", text: a.coop_name + ": " + a.level });
return { payload: { farm_id: a.farm_id, data: { type: "alert", coop_id: a.coop_id, level: a.level, message: a.message, at } } };

// กฎ: เทียบค่ากับเป้าหมายของโรงเรือนนั้น (ปรับตามอายุไก่ ดูแท็บ "ข้อมูลฟาร์ม") แจ้งเฉพาะตอนสถานะเปลี่ยน
const r = msg.reading;
const coop = (global.get("coops") || []).find(c => c.id === r.coop_id);
if (!coop) return null;
const t = coop.target;
const why = coop.flock ? " (ไก่อายุ " + coop.flock.age_days + " วัน ควรอยู่ " + t.temp_min + "–" + t.temp_max + " °C)"
                       : " (เกณฑ์ " + t.temp_min + "–" + t.temp_max + " °C)";
let level = "ok", message = "กลับมาอยู่ในเกณฑ์แล้ว";
if (r.temp > t.temp_max)          { level = "hot";  message = "ร้อนเกินไป " + r.temp + " °C" + why; }
else if (r.temp < t.temp_min)     { level = "cold"; message = "หนาวเกินไป " + r.temp + " °C" + why; }
else if (r.humidity > t.hum_max)  { level = "wet";  message = "ชื้นเกินไป " + r.humidity + " % (ควรอยู่ " + t.hum_min + "–" + t.hum_max + " %)"; }
else if (r.humidity < t.hum_min)  { level = "dry";  message = "แห้งเกินไป " + r.humidity + " % (ควรอยู่ " + t.hum_min + "–" + t.hum_max + " %)"; }
const key = "alert_" + r.coop_id, prev = flow.get(key);
if (prev === level) return null;
flow.set(key, level);
if (prev === undefined && level === "ok") return null;     // เพิ่งเริ่มระบบและปกติดี
return { alert: { farm_id: coop.farm_id, coop_id: coop.id, coop_name: coop.name, level, message, temp: r.temp, humidity: r.humidity } };

// อุปกรณ์ที่ผ่านการตรวจของ gateway แต่ยังไม่ได้ลงทะเบียนเป็นโรงเรือน: บันทึกไว้ให้ผู้ดูแลเห็นในหน้า "จัดการฟาร์ม"
const scf = global.get("scf");
const d = msg.payload;
const gw = (global.get("gateways") || []).find(g => g.mqtt_user === d.mqtt_user);
const farmId = gw ? gw.farm_id : null;
const message = "พบอุปกรณ์ที่ยังไม่ลงทะเบียน: " + d.mqtt_user + " โหนด " + d.node_id;
node.warn(message);
try {
    await scf.db.insert("audit_log", { action: "unknown_device", farm_id: farmId, detail: d });
    await scf.db.insert("alerts", { farm_id: farmId, coop_id: null, level: "unknown", message });
} catch (e) { node.error(e.message); }
return farmId ? { payload: { farm_id: farmId, data: { type: "alert", coop_id: null, level: "unknown", message, at: new Date().toISOString() } } } : null;

// ระบุอุปกรณ์: topic scf/<gateway>/node/<n>/telemetry -> โรงเรือนไหน ฟาร์มไหน
// - Mosquitto ACL ทำให้ gateway เขียนได้เฉพาะ scf/<ชื่อตัวเอง>/... จึงปลอมเป็น gateway อื่นไม่ได้
// - gateway ตรวจ HMAC ของแพ็กเก็ต ESP-NOW ก่อนส่งต่อ จึงปลอมเป็นโหนดไม่ได้
// - ที่นี่: รับเฉพาะ (gateway, โหนด) ที่ลงทะเบียนเป็นโรงเรือนแล้ว + ตรวจช่วงค่า + จำกัดความถี่
// outputs: 1 บันทึก, 2 กฎ, 3 ส่งข้อมูลสด, 4 อุปกรณ์ที่ยังไม่ลงทะเบียน
const m = /^scf\/(gw[a-z0-9-]{1,30})\/node\/([0-9]{1,2})\/telemetry$/.exec(msg.topic);
if (!m) return null;
const gw = m[1], nodeId = Number(m[2]);
const coop = (global.get("coops") || []).find(c => c.active && c.mqtt_user === gw && c.node_id === nodeId);
if (!coop) {
    const k = "unknown_" + gw + "_" + nodeId, last = flow.get(k) || 0;
    const unknown = global.get("unknownDevices") || {};
    unknown[gw + ":" + nodeId] = { mqtt_user: gw, node_id: nodeId, last_seen: new Date().toISOString() };
    global.set("unknownDevices", unknown);
    if (Date.now() - last < 10 * 60000) return null;          // แจ้งไม่เกิน 1 ครั้ง / 10 นาที
    flow.set(k, Date.now());
    return [null, null, null, { payload: { mqtt_user: gw, node_id: nodeId } }];
}
const d = msg.payload;
if (!d || typeof d !== "object" || !Number.isFinite(d.temp) || !Number.isFinite(d.humidity)
    || d.temp < -40 || d.temp > 125 || d.humidity < 0 || d.humidity > 100) {
    node.warn("ค่าผิดรูปแบบ/เกินช่วงเซนเซอร์ " + msg.topic + " " + JSON.stringify(d));
    return null;
}
const rk = "rate_" + coop.id, now = Date.now();
if (now - (flow.get(rk) || 0) < 2000) return null;            // กัน flood: ไม่เกิน 1 ค่า / 2 วินาที / โรงเรือน
flow.set(rk, now);
flow.set("lastSeen_" + coop.id, now);
const temp = Math.round(d.temp * 100) / 100, humidity = Math.round(d.humidity * 100) / 100;
const live = global.get("live") || {};
live[coop.id] = Object.assign({}, live[coop.id], { temp, humidity, at: new Date(now).toISOString() });
global.set("live", live);
const reading = { coop_id: coop.id, farm_id: coop.farm_id, temp, humidity };
node.status({ fill: "green", shape: "dot", text: coop.name + ": " + temp + "°C " + humidity + "%" });
return [{ reading }, { reading },
        { payload: { farm_id: coop.farm_id, data: { type: "telemetry", coop_id: coop.id, temp, humidity, at: live[coop.id].at } } }, null];

// ทุก 5 วิ: โรงเรือนที่เคยส่งข้อมูลแล้วเงียบเกิน 30 วิ = ขาดการติดต่อ (โหนดดับ / gateway ดับ / สัญญาณหลุด)
const OFFLINE_MS = 30000, out = [];
for (const c of global.get("coops") || []) {
    if (!c.active) continue;
    const seen = flow.get("lastSeen_" + c.id);
    if (!seen || Date.now() - seen <= OFFLINE_MS) continue;
    const key = "alert_" + c.id;
    if (flow.get(key) === "offline") continue;
    flow.set(key, "offline");
    out.push({ alert: { farm_id: c.farm_id, coop_id: c.id, coop_name: c.name, level: "offline",
                        message: "ขาดการติดต่อ: ไม่ได้รับข้อมูลเกิน 30 วินาที", temp: null, humidity: null } });
}
return [out];

// สถานะไฟจริงที่โหนดยืนยัน (ACK): scf/<gateway>/node/<n>/light/state
// บันทึกลง led_events เฉพาะตอนเปลี่ยนจริง และส่งให้หน้าจอทันที
const scf = global.get("scf");
const m = /^scf\/(gw[a-z0-9-]{1,30})\/node\/([0-9]{1,2})\/light\/state$/.exec(msg.topic);
if (!m) return null;
const coop = (global.get("coops") || []).find(c => c.active && c.mqtt_user === m[1] && c.node_id === Number(m[2]));
if (!coop) return null;
const on = String(msg.payload).trim().toUpperCase() === "ON";
const live = global.get("live") || {};
const prev = live[coop.id] && live[coop.id].ledKnown ? live[coop.id].led : undefined;
live[coop.id] = Object.assign({}, live[coop.id], { led: on, ledKnown: true });
global.set("live", live);
node.status({ fill: on ? "yellow" : "grey", shape: "dot", text: coop.name + ": " + (on ? "ON" : "OFF") });
const out = { payload: { farm_id: coop.farm_id, data: { type: "light", coop_id: coop.id, on } } };
// retained = old state replayed by the broker on (re)connect; same as before = gateway re-announcing it
if (!msg.retain && prev !== on) {
    try { await scf.db.insert("led_events", { coop_id: coop.id, state: on }); }
    catch (e) { node.error("บันทึกสถานะไฟไม่สำเร็จ: " + e.message); }
}
return out;

// scf/<gateway>/status = online / offline (offline is the gateway's MQTT Last Will, sent by the broker)
const scf = global.get("scf");
const m = /^scf\/(gw[a-z0-9-]{1,30})\/status$/.exec(msg.topic);
if (!m) return null;
const online = String(msg.payload).trim() === "online";
const status = global.get("gwOnline") || {};
status[m[1]] = online;
global.set("gwOnline", status);
const gw = (global.get("gateways") || []).find(g => g.mqtt_user === m[1]);
node.status({ fill: online ? "green" : "red", shape: online ? "dot" : "ring", text: m[1] + " " + (online ? "online" : "offline") });
if (!gw) return null;
if (online && !msg.retain) scf.db.update("gateways", "id=eq." + gw.id, { last_seen: new Date().toISOString() }).catch(e => node.warn(e.message));
return { payload: { farm_id: gw.farm_id, data: { type: "gateway", gateway_id: gw.id, online } } };

// scf/<gateway>/security: gateway พบแพ็กเก็ต ESP-NOW ปลอม (HMAC ผิด) หรือส่งซ้ำ (replay) -> แจ้งเตือน + บันทึก
const scf = global.get("scf");
const m = /^scf\/(gw[a-z0-9-]{1,30})\/security$/.exec(msg.topic);
const d = msg.payload;
if (!m || !d || typeof d !== "object") return null;
const n = k => Math.max(0, Math.min(1e6, Number(d[k]) || 0));
const report = { bad_tag: n("bad_tag"), replay: n("replay"), bad_format: n("bad_format") };
if (!report.bad_tag && !report.replay && !report.bad_format) return null;
const gw = (global.get("gateways") || []).find(g => g.mqtt_user === m[1]);
const farmId = gw ? gw.farm_id : null;
const message = "ตรวจพบแพ็กเก็ตที่ไม่ผ่านการยืนยันที่ " + m[1] + ": HMAC ผิด " + report.bad_tag + " · ส่งซ้ำ " + report.replay + " · รูปแบบผิด " + report.bad_format + " (อาจมีอุปกรณ์แปลกปลอม)";
node.warn(message);
try {
    await scf.db.insert("audit_log", { action: "sensor_security", farm_id: farmId, detail: Object.assign({ gateway: m[1] }, report) });
    await scf.db.insert("alerts", { farm_id: farmId, coop_id: null, level: "security", message });
} catch (e) { node.error(e.message); }
return farmId ? { payload: { farm_id: farmId, data: { type: "alert", coop_id: null, level: "security", message, at: new Date().toISOString() } } } : null;

// จำคำสั่งไฟล่าสุดของแต่ละโรงเรือน (ตัวตั้งเวลาใช้เทียบว่าต้องสั่งใหม่ไหม)
const m = /^scf\/(gw[a-z0-9-]{1,30})\/node\/([0-9]{1,2})\/light\/set$/.exec(msg.topic);
if (!m) return null;
const coop = (global.get("coops") || []).find(c => c.mqtt_user === m[1] && c.node_id === Number(m[2]));
if (coop) flow.set("set_" + coop.id, String(msg.payload).trim().toUpperCase() === "ON");
return msg;

// โหลดข้อมูลทุกฟาร์มเก็บใน memory (global): ฟาร์ม, gateway, โรงเรือน+รุ่นไก่, ผู้ใช้ (+ โรงเรือนของผู้ดูแลโรงเรือน)
// แล้วคำนวณอายุไก่ + เป้าหมายอุณหภูมิของแต่ละโรงเรือน
// โหลดตอนเริ่ม, ทุก 5 นาที (อายุไก่เปลี่ยนตามวัน) และทุกครั้งที่มีการแก้ข้อมูลจากเว็บ
// outputs: 1 แจ้งหน้าจอว่าข้อมูลเปลี่ยน, 2 ปลุกตัวตั้งเวลาไฟ
const scf = global.get("scf");

// เป้าหมายอุณหภูมิไก่เนื้อตามอายุ (ประมาณจากคู่มือ Ross/Cobb), ช่วงที่ยอมรับ = เป้าหมาย ±3 °C
const TEMP_BY_AGE = [[0, 32], [7, 29], [14, 27], [21, 25], [28, 23], [35, 21], [42, 20]];
const BAND = 3;
const ideal = age => {
    for (let i = 1; i < TEMP_BY_AGE.length; i++) {
        const [a1, t1] = TEMP_BY_AGE[i - 1], [a2, t2] = TEMP_BY_AGE[i];
        if (age <= a2) return t1 + (t2 - t1) * (Math.max(age, 0) - a1) / (a2 - a1);
    }
    return TEMP_BY_AGE[TEMP_BY_AGE.length - 1][1];
};
const num = (k, d) => { const v = Number(env.get(k)); return env.get(k) != null && env.get(k) !== "" && Number.isFinite(v) ? v : d; };
const DEF = { temp_min: num("TEMP_MIN", 18), temp_max: num("TEMP_MAX", 30), hum_min: num("HUM_MIN", 50), hum_max: num("HUM_MAX", 70) };
const r1 = v => Math.round(v * 10) / 10;
const now = new Date();
const today = Date.UTC(now.getFullYear(), now.getMonth(), now.getDate());
const ageOf = ymd => { const [y, m, d] = String(ymd).split("-").map(Number); return Math.max(0, Math.round((today - Date.UTC(y, m - 1, d)) / 864e5)); };

try {
    let [farms, gateways, coops, users, latest, userCoops] = await Promise.all([
        scf.db.get("farms?select=id,name,location,active,created_at&order=id"),
        scf.db.get("gateways?select=id,farm_id,name,mqtt_user,active,last_seen,created_at&order=id"),
        scf.db.get("coop_state?select=*&order=id"),
        scf.db.get("users?select=id,username,display_name,role,farm_id,active,session_version,last_login,locked_until,totp_enabled&order=id"),
        scf.db.get("latest_readings?select=coop_id,temp,humidity,created_at"),
        scf.db.get("user_coops?select=user_id,coop_id&order=coop_id"),
        scf.db.get("farms?select=farm_key&limit=1"),      // v3.3 schema check: fails = setup.sql not run yet
    ]);

    // very first start: create the first admin from ADMIN_PASSWORD in .env
    if (!users.length) {
        const pw = env.get("ADMIN_PASSWORD") || "";
        if (scf.passwordProblem(pw)) node.error("ยังไม่มีผู้ใช้ และ ADMIN_PASSWORD ใน .env ใช้ไม่ได้: " + scf.passwordProblem(pw));
        else {
            await scf.db.insert("users", { username: "admin", display_name: "ผู้ดูแลระบบ", password_hash: scf.hashPassword(pw), role: "admin" });
            await scf.db.insert("audit_log", { username: "system", action: "bootstrap_admin", detail: { username: "admin" } });
            users = await scf.db.get("users?select=id,username,display_name,role,farm_id,active,session_version,last_login,locked_until,totp_enabled&order=id");
            node.warn("สร้างบัญชีผู้ดูแลระบบแรก (admin) แล้ว");
        }
    }

    // v3.3: keep the first farm's FARM_KEY (from .env, already in firmware/*/secrets.h) so the web can hand out board files
    if (!flow.get("farmKeyChecked")) {
        const gw1 = gateways.find(g => g.mqtt_user === "gw1"), key = String(env.get("FARM_KEY") || "").toLowerCase();
        if (gw1 && scf.FARM_KEY_RE.test(key)) {
            try { await scf.db.update("farms", "id=eq." + gw1.farm_id + "&farm_key=is.null", { farm_key: key }); }
            catch (e) { node.warn("farm_key: " + e.message); }
        }
        flow.set("farmKeyChecked", true);
    }
    // ฉุกเฉิน: MFA_RESET_USER=<ชื่อผู้ใช้> ใน .env แล้วรัน start.sh = ปิด 2 ขั้นของคนนั้น (เช่น admin คนเดียวทำมือถือหาย)
    const resetName = String(env.get("MFA_RESET_USER") || "").trim().toLowerCase();
    if (resetName && flow.get("mfaResetDone") !== resetName) {
        const t = users.find(u => u.username === resetName);
        if (t) {
            await scf.db.update("users", "id=eq." + t.id, { totp_secret: null, totp_enabled: false, totp_last_step: null, mfa_backup: null,
                                                           session_version: (t.session_version || 0) + 1 });
            t.totp_enabled = false; t.session_version = (t.session_version || 0) + 1;
            await scf.db.insert("audit_log", { username: "system", action: "mfa_reset", detail: { target: t.username, by: "MFA_RESET_USER" } });
            node.warn("ปิดการยืนยันตัวตน 2 ขั้นของ " + t.username + " แล้ว (เอา MFA_RESET_USER ออกจาก .env ได้)");
        }
        flow.set("mfaResetDone", resetName);
    }
    const gwById = Object.fromEntries(gateways.map(g => [g.id, g]));
    const list = coops.map(r => {
        let flock = null, target = Object.assign({}, DEF, { temp_ideal: null, by_age: false });
        if (r.flock_id) {
            const age = ageOf(r.started_on), deaths = Number(r.deaths) || 0;
            flock = { id: Number(r.flock_id), started_on: r.started_on, birds: Number(r.birds), breed: r.breed, age_days: age, deaths,
                      alive: Math.max(0, Number(r.birds) - deaths), feed_kg: r1(Number(r.feed_kg) || 0),
                      avg_weight_g: r.avg_weight_g == null ? null : Number(r.avg_weight_g), last_log_date: r.last_log_date || null };
            const t = ideal(age);
            target = { temp_min: r1(t - BAND), temp_max: r1(t + BAND), temp_ideal: r1(t), hum_min: age < 7 ? 60 : 50, hum_max: 70, by_age: true };
        }
        const gw = gwById[r.gateway_id];
        return { id: Number(r.id), farm_id: Number(r.farm_id), name: r.name, capacity: r.capacity, gateway_id: r.gateway_id,
                 mqtt_user: gw && gw.active ? r.mqtt_user : null, node_id: r.node_id, light_mode: r.light_mode,
                 light_on: r.light_on, light_off: r.light_off, active: r.active, flock, target };
    });

    const live = global.get("live") || {};
    for (const l of latest) {
        if (!live[l.coop_id] || !live[l.coop_id].at) live[l.coop_id] = Object.assign({}, live[l.coop_id], { temp: l.temp, humidity: l.humidity, at: l.created_at });
    }
    global.set("live", live);
    global.set("farms", farms);
    global.set("gateways", gateways);
    global.set("coops", list);
    const coopIds = {};
    for (const r of userCoops) (coopIds[r.user_id] = coopIds[r.user_id] || []).push(Number(r.coop_id));
    global.set("users", Object.fromEntries(users.map(u => [u.id, Object.assign(u, { coop_ids: coopIds[u.id] || [] })])));
    global.set("cacheReady", true);
    node.status({ fill: "green", shape: "dot", text: farms.length + " ฟาร์ม · " + list.filter(c => c.active).length + " โรงเรือน · " + users.length + " ผู้ใช้" });
    return [{ payload: { farm_id: null, data: { type: "config" } } }, { payload: "run" }];
} catch (e) {
    node.status({ fill: "red", shape: "ring", text: "โหลดไม่ได้: " + e.message.slice(0, 40) });
    node.error("โหลดข้อมูลฟาร์มไม่ได้ (รัน supabase/setup.sql แล้วหรือยัง?): " + e.message);
    return null;
}

// POST /api/login {username, password}
// - รหัสผ่านตรวจด้วย scrypt (เทียบแบบเวลาเท่ากัน)
// - ผิด 5 ครั้งติด ล็อกบัญชี 5 นาที / IP เดียวผิดเกิน 20 ครั้งใน 10 นาที บล็อกชั่วคราว
// - สำเร็จ: ได้ token ที่ลงลายเซ็นไว้ อายุ 12 ชม. ทุกครั้งบันทึกลง audit_log
// - เปิดยืนยันตัวตน 2 ขั้นไว้ (หรือบทบาทบังคับใช้) = ยังไม่ได้ token: ได้ "ตั๋ว" 5 นาทีไปกรอกรหัส 6 หลักที่ POST /auth/mfa
const scf = global.get("scf");
const b = (msg.payload && typeof msg.payload === "object") ? msg.payload : {};
const username = String(b.username || "").trim().toLowerCase();
const password = String(b.password || "");
const ip = String((msg.req.headers && msg.req.headers["x-forwarded-for"]) || msg.req.ip || "").split(",")[0].trim();

const ipKey = "ipfail_" + ip;
let rec = flow.get(ipKey) || { n: 0, t: Date.now() };
if (Date.now() - rec.t > 10 * 60000) rec = { n: 0, t: Date.now() };
if (rec.n >= 20) return scf.reply(msg, 429, { error: "ลองเข้าสู่ระบบผิดหลายครั้งเกินไป กรุณารอ 10 นาที" });

const audit = (action, u, detail) => scf.db.insert("audit_log", {
    user_id: u ? u.id : null, username: u ? u.username : username.slice(0, 32) || null, farm_id: u ? u.farm_id : null, action, detail,
}).catch(e => node.warn("audit: " + e.message));
const denied = async (u, reason) => {
    rec.n++; flow.set(ipKey, rec);
    await audit("login_fail", u, { reason, ip });
    return scf.reply(msg, 401, { error: "ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง" });
};

try {
    if (!/^[a-z0-9._-]{3,32}$/.test(username) || !password || password.length > 128) return await denied(null, "format");
    const u = (await scf.db.get("users?select=*&username=eq." + username))[0];
    if (!u) {
        let dummy = flow.get("dummyHash");
        if (!dummy) { dummy = scf.hashPassword("not-a-real-password-1"); flow.set("dummyHash", dummy); }
        scf.verifyPassword(password, dummy);                       // same time as a real check: no user enumeration
        return await denied(null, "no_user");
    }
    if (u.locked_until && Date.parse(u.locked_until) > Date.now()) {
        await audit("login_locked", u, { ip });
        return scf.reply(msg, 423, { error: "บัญชีถูกล็อกชั่วคราวเพราะใส่รหัสผิดหลายครั้ง ลองใหม่หลัง " +
            new Date(u.locked_until).toLocaleTimeString("th-TH", { hour: "2-digit", minute: "2-digit" }) + " น." });
    }
    if (!scf.verifyPassword(password, u.password_hash)) {
        const n = (u.failed_logins || 0) + 1, lock = n >= 5;
        await scf.db.update("users", "id=eq." + u.id, { failed_logins: lock ? 0 : n, locked_until: lock ? new Date(Date.now() + 5 * 60000).toISOString() : null });
        return await denied(u, lock ? "locked_now" : "password");
    }
    if (!u.active) return await denied(u, "inactive");
    if (u.role !== "admin") {                                // ผู้ดูแลฟาร์ม/ผู้ดู: ฟาร์มของตัวเองต้องยังเปิดใช้งาน
        const farm = (global.get("farms") || []).find(f => f.id === u.farm_id);
        if (!farm || !farm.active) return await denied(u, "farm_inactive");
    }
    // ---- ขั้นที่ 2: รหัสจากแอป Authenticator (TOTP)
    const ticket = scf.signToken(u, 300, "mfa");
    if (u.totp_enabled) {
        await audit("login_password_ok", u, { ip });
        return scf.reply(msg, 200, { mfa: "code", mfa_token: ticket, expires_in: 300 });
    }
    if (scf.mfaRequired(u)) {                              // บทบาทนี้ต้องใช้ แต่ยังไม่ได้ตั้งค่า: ตั้งค่าเดี๋ยวนี้ก่อนเข้าระบบ
        const secret = scf.newTotpSecret();
        await scf.db.update("users", "id=eq." + u.id, { totp_secret: scf.sealSecret(secret), totp_enabled: false, totp_last_step: null });
        await audit("login_password_ok", u, { ip, mfa_setup: true });
        return scf.reply(msg, 200, { mfa: "setup", mfa_token: ticket, expires_in: 300, secret, otpauth: scf.otpauthUrl(u.username, secret),
                                     username: u.username, display_name: u.display_name });
    }
    await scf.db.update("users", "id=eq." + u.id, { failed_logins: 0, locked_until: null, last_login: new Date().toISOString() });
    await audit("login_ok", u, { ip });
    rec.n = 0; flow.set(ipKey, rec);
    u.coop_ids = ((global.get("users") || {})[u.id] || {}).coop_ids || [];
    return scf.reply(msg, 200, { token: scf.signToken(u), expires_in: scf.TOKEN_TTL, user: Object.assign(scf.publicUser(u), { perms: scf.permsOf(u) }) });
} catch (e) {
    node.error("login: " + e.message);
    return scf.errorReply(msg, e);
}

// ---- ส่วนกลางของทุก API (ตรวจสิทธิ์ + ตัวช่วย) ----
const scf = global.get("scf");
const user = msg.user, q = msg.q, b = msg.body, R = msg.resource;
const farms = global.get("farms") || [], coops = global.get("coops") || [], gateways = global.get("gateways") || [];
const isAdmin = user.role === "admin";
const fail = scf.fail;
// สิทธิ์: ไม่ผ่าน = 403 ทันที (ผู้ใช้ที่ไม่ใช่ admin ทำได้เฉพาะในฟาร์มของตัวเอง · ผู้ดูแลโรงเรือนเฉพาะโรงเรือนของตัวเอง)
const need = (perm, farmId, coopId) => { if (!scf.can(user, perm, farmId, coopId)) throw fail(403, "คุณไม่มีสิทธิ์ทำรายการนี้"); };
// ฟาร์มที่คำขอนี้หมายถึง: admin เลือกได้ (ไม่ระบุ = ฟาร์มแรกที่เปิดใช้งาน), คนอื่นได้ฟาร์มตัวเองเท่านั้น (ขอฟาร์มอื่น = 403)
const farmParam = () => {
    const asked = scf.int(q.farm_id != null ? q.farm_id : b.farm_id);
    if (!isAdmin) {
        if (asked && asked !== user.farm_id) throw fail(403, "คุณเข้าถึงได้เฉพาะฟาร์มของตัวเอง");
        return user.farm_id;
    }
    return asked || (farms.find(f => f.active) || farms[0] || {}).id || null;
};
const farmOf = id => { const f = farms.find(f => f.id === scf.int(id)); if (!f || !scf.seesFarm(user, f.id)) throw fail(404, "ไม่พบฟาร์ม"); return f; };
// โรงเรือนในฟาร์มอื่น (หรือที่ผู้ดูแลโรงเรือนไม่ได้ดูแล) ตอบว่า "ไม่พบ" (ไม่บอกว่ามีอยู่)
const coopOf = id => { const c = coops.find(c => c.id === scf.int(id)); if (!c || !scf.seesCoop(user, c)) throw fail(404, "ไม่พบโรงเรือน"); return c; };
const text = (v, max, label, required = true) => {
    const s = String(v == null ? "" : v).trim();
    if (required && !s) throw fail(400, "กรุณากรอก" + label);
    if (s.length > max) throw fail(400, label + "ยาวเกิน " + max + " ตัวอักษร");
    return s || null;
};
const isDate = s => /^\d{4}-\d{2}-\d{2}$/.test(String(s)) && !isNaN(Date.parse(s));
const isTime = s => /^([01]\d|2[0-3]):[0-5]\d$/.test(String(s));
const pad = n => String(n).padStart(2, "0");
const todayStr = (() => { const d = new Date(); return d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate()); })();
const since = () => q.since && !isNaN(Date.parse(q.since)) ? new Date(q.since).toISOString() : null;
const limit = (d, max = 1000) => Math.min(Math.max(parseInt(q.limit, 10) || d, 1), max);
const audit = (action, farmId, detail) => scf.db.insert("audit_log", {
    user_id: user.id, username: user.username, farm_id: farmId == null ? null : farmId, action, detail: detail == null ? null : detail,
}).catch(e => node.warn("audit: " + e.message));
// outputs: 1 ตอบเว็บ, 2 MQTT (คำสั่งไฟ), 3 โหลดข้อมูลฟาร์มใหม่, 4 ส่งข้อมูลสด
const done = (body, extra = {}) => { node.send([scf.reply(msg, 200, body), extra.mqtt || null, extra.reload ? { payload: "reload" } : null, extra.live || null]); };
const run = async fn => {
    try { await fn(); }
    catch (e) {
        if (!e.http && e.code !== "23505") node.error(R + ": " + e.message);
        node.send([scf.errorReply(msg, e), null, null, null]);
    }
};
// ---- จบส่วนกลาง ----

// GET: me · farms · farm-data · readings · led-events · alerts · daily-logs · audit
// ทุกข้อมูลกรองด้วยฟาร์มที่ผู้ใช้มีสิทธิ์ที่ server (ไม่ใช่แค่ซ่อนในหน้าเว็บ)
await run(async () => {
    if (msg.method !== "GET") throw fail(405, "method not allowed");
    const visibleFarms = farms.filter(f => scf.seesFarm(user, f.id));
    const users = Object.values(global.get("users") || {});
    const keepersOf = fid => users.filter(u => u.active && u.role === "keeper" && u.farm_id === fid);
    // ผู้ดูแลโรงเรือนของแต่ละโรง (ชื่อที่แสดง)
    const caretakersOf = cid => users.filter(u => u.active && u.role === "coop_keeper" && scf.coopIdsOf(u).includes(cid)).map(u => u.display_name);

    if (R === "me") return done({ user: Object.assign(scf.publicUser(user), { perms: scf.permsOf(user) }),
                                  farms: visibleFarms.map(f => ({ id: f.id, name: f.name, active: f.active })),
                                  // ที่อยู่เว็บสำหรับส่งให้คนอื่น (IP ของเครื่อง server ใน Wi-Fi จาก start.sh)
                                  lan_url: /^[0-9.]{7,15}$/.test(env.get("SERVER_IP") || "") ? "http://" + env.get("SERVER_IP") + ":1880/" : null });

    if (R === "farms") {
        need("view", isAdmin ? null : user.farm_id);
        return done(visibleFarms.map(f => {
            const fc = coops.filter(c => c.farm_id === f.id && c.active);
            return { id: f.id, name: f.name, location: f.location, active: f.active, created_at: f.created_at,
                     coops: fc.length, birds: fc.reduce((s, c) => s + (c.flock ? c.flock.alive : 0), 0),
                     gateways: gateways.filter(g => g.farm_id === f.id && g.active).length,
                     keepers: keepersOf(f.id).map(u => u.display_name),
                     staff: users.filter(u => u.farm_id === f.id && u.active).length,
                     // หน้าผู้ใช้: รายชื่อโรงเรือนให้เลือกตอนมอบหมายผู้ดูแลโรงเรือน
                     coop_list: scf.can(user, "staff_manage", f.id)
                         ? coops.filter(c => c.farm_id === f.id).map(c => ({ id: c.id, name: c.name, active: c.active })) : undefined };
        }));
    }

    if (R === "farm-data") {
        const fid = farmParam();
        if (!fid) return done({ farm: null, coops: [], gateways: [], keepers: [], unknown_devices: [] });
        need("view", fid);
        const farm = farmOf(fid);
        const live = global.get("live") || {}, gwOnline = global.get("gwOnline") || {};
        const canManage = scf.can(user, "coop_manage", fid);
        const farmGws = gateways.filter(g => g.farm_id === fid);
        const unknown = !canManage ? [] : Object.values(global.get("unknownDevices") || {})
            .filter(d => farmGws.some(g => g.mqtt_user === d.mqtt_user) && !coops.some(c => c.active && c.mqtt_user === d.mqtt_user && c.node_id === d.node_id));
        return done({
            farm: { id: farm.id, name: farm.name, location: farm.location, active: farm.active },
            coops: coops.filter(c => c.farm_id === fid && (c.active || canManage) && scf.seesCoop(user, c)).map(c => Object.assign({}, c, {
                live: live[c.id] || null,
                gateway_name: (farmGws.find(g => g.id === c.gateway_id) || {}).name || null,
                caretakers: caretakersOf(c.id),
            })),
            gateways: farmGws.map(g => ({ id: g.id, name: g.name, mqtt_user: canManage ? g.mqtt_user : undefined, active: g.active,
                                          online: !!gwOnline[g.mqtt_user], last_seen: g.last_seen })),
            keepers: keepersOf(fid).map(u => u.display_name),
            unknown_devices: unknown,
        });
    }

    // history: one coop (coop_id) or every coop of the farm
    const scope = () => {
        if (q.coop_id) { const c = coopOf(q.coop_id); need("view", c.farm_id); return [c.id]; }
        const fid = farmParam();
        if (!fid) throw fail(400, "ต้องระบุฟาร์ม");
        need("view", fid);
        return coops.filter(c => c.farm_id === fid && scf.seesCoop(user, c)).map(c => c.id);
    };
    const sinceQ = () => since() ? "&created_at=gte." + since() : "";

    if (R === "readings") {
        const ids = scope();
        if (!ids.length) return done([]);
        const order = q.order === "asc" ? "asc" : "desc";
        return done(await scf.db.get("readings?select=coop_id,temp,humidity,created_at&coop_id=" + scf.inList(ids) +
            sinceQ() + "&order=created_at." + order + "&limit=" + limit(100)));
    }
    if (R === "led-events") {
        const ids = scope();
        if (!ids.length) return done([]);
        return done(await scf.db.get("led_events?select=coop_id,state,created_at&coop_id=" + scf.inList(ids) +
            sinceQ() + "&order=created_at.asc&limit=2000"));
    }
    if (R === "alerts") {
        let filter;
        if (q.coop_id) { const c = coopOf(q.coop_id); need("view", c.farm_id); filter = "coop_id=eq." + c.id; }
        else {
            const fid = farmParam(); if (!fid) return done([]); need("view", fid);
            filter = "farm_id=eq." + fid;
            if (user.role === "coop_keeper") {             // ผู้ดูแลโรงเรือน: เฉพาะแจ้งเตือนของโรงเรือนตัวเอง
                const mine = coops.filter(c => c.farm_id === fid && scf.seesCoop(user, c)).map(c => c.id);
                if (!mine.length) return done([]);
                filter = "coop_id=" + scf.inList(mine);
            }
        }
        return done(await scf.db.get("alerts?select=id,coop_id,level,message,temp,humidity,created_at&" + filter +
            sinceQ() + "&order=created_at.desc&limit=" + limit(100)));
    }
    if (R === "daily-logs") {
        const c = coopOf(q.coop_id);
        need("view", c.farm_id);
        if (!c.flock) return done([]);
        return done(await scf.db.get("daily_logs?select=log_date,deaths,feed_kg,avg_weight_g,note,created_by&flock_id=eq." +
            c.flock.id + "&order=log_date.desc&limit=400"));
    }
    if (R === "audit") {
        need("audit_view", null);
        const fid = q.all ? null : farmParam();
        return done(await scf.db.get("audit_log?select=id,username,farm_id,action,detail,created_at" + (fid ? "&farm_id=eq." + fid : "") + sinceQ() +
            "&order=created_at.desc&limit=" + limit(200, 1000)));
    }
    throw fail(404, "ไม่รู้จัก " + R);
});
return null;

// ---- ส่วนกลางของทุก API (ตรวจสิทธิ์ + ตัวช่วย) ----
const scf = global.get("scf");
const user = msg.user, q = msg.q, b = msg.body, R = msg.resource;
const farms = global.get("farms") || [], coops = global.get("coops") || [], gateways = global.get("gateways") || [];
const isAdmin = user.role === "admin";
const fail = scf.fail;
// สิทธิ์: ไม่ผ่าน = 403 ทันที (ผู้ใช้ที่ไม่ใช่ admin ทำได้เฉพาะในฟาร์มของตัวเอง · ผู้ดูแลโรงเรือนเฉพาะโรงเรือนของตัวเอง)
const need = (perm, farmId, coopId) => { if (!scf.can(user, perm, farmId, coopId)) throw fail(403, "คุณไม่มีสิทธิ์ทำรายการนี้"); };
// ฟาร์มที่คำขอนี้หมายถึง: admin เลือกได้ (ไม่ระบุ = ฟาร์มแรกที่เปิดใช้งาน), คนอื่นได้ฟาร์มตัวเองเท่านั้น (ขอฟาร์มอื่น = 403)
const farmParam = () => {
    const asked = scf.int(q.farm_id != null ? q.farm_id : b.farm_id);
    if (!isAdmin) {
        if (asked && asked !== user.farm_id) throw fail(403, "คุณเข้าถึงได้เฉพาะฟาร์มของตัวเอง");
        return user.farm_id;
    }
    return asked || (farms.find(f => f.active) || farms[0] || {}).id || null;
};
const farmOf = id => { const f = farms.find(f => f.id === scf.int(id)); if (!f || !scf.seesFarm(user, f.id)) throw fail(404, "ไม่พบฟาร์ม"); return f; };
// โรงเรือนในฟาร์มอื่น (หรือที่ผู้ดูแลโรงเรือนไม่ได้ดูแล) ตอบว่า "ไม่พบ" (ไม่บอกว่ามีอยู่)
const coopOf = id => { const c = coops.find(c => c.id === scf.int(id)); if (!c || !scf.seesCoop(user, c)) throw fail(404, "ไม่พบโรงเรือน"); return c; };
const text = (v, max, label, required = true) => {
    const s = String(v == null ? "" : v).trim();
    if (required && !s) throw fail(400, "กรุณากรอก" + label);
    if (s.length > max) throw fail(400, label + "ยาวเกิน " + max + " ตัวอักษร");
    return s || null;
};
const isDate = s => /^\d{4}-\d{2}-\d{2}$/.test(String(s)) && !isNaN(Date.parse(s));
const isTime = s => /^([01]\d|2[0-3]):[0-5]\d$/.test(String(s));
const pad = n => String(n).padStart(2, "0");
const todayStr = (() => { const d = new Date(); return d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate()); })();
const since = () => q.since && !isNaN(Date.parse(q.since)) ? new Date(q.since).toISOString() : null;
const limit = (d, max = 1000) => Math.min(Math.max(parseInt(q.limit, 10) || d, 1), max);
const audit = (action, farmId, detail) => scf.db.insert("audit_log", {
    user_id: user.id, username: user.username, farm_id: farmId == null ? null : farmId, action, detail: detail == null ? null : detail,
}).catch(e => node.warn("audit: " + e.message));
// outputs: 1 ตอบเว็บ, 2 MQTT (คำสั่งไฟ), 3 โหลดข้อมูลฟาร์มใหม่, 4 ส่งข้อมูลสด
const done = (body, extra = {}) => { node.send([scf.reply(msg, 200, body), extra.mqtt || null, extra.reload ? { payload: "reload" } : null, extra.live || null]); };
const run = async fn => {
    try { await fn(); }
    catch (e) {
        if (!e.http && e.code !== "23505") node.error(R + ": " + e.message);
        node.send([scf.errorReply(msg, e), null, null, null]);
    }
};
// ---- จบส่วนกลาง ----

// POST: light · lights-off · settings · flock · flock-end · daily-log
//   ทุกคำสั่งตรวจว่าโรงเรือนอยู่ในฟาร์มของผู้ใช้ (ผู้ดูแลฟาร์ม = ฟาร์มตัวเอง, admin = ทุกฟาร์ม)
//   light, settings, flock(-end), daily-log   ผู้ดูแลโรงเรือน (เฉพาะโรงเรือนของตัวเอง) ผู้ดูแลฟาร์ม และผู้ดูแลระบบ
//   lights-off                                ผู้ดูแลฟาร์มขึ้นไป: ปิดไฟทุกโรงเรือนของฟาร์มพร้อมกันด้วยปุ่มเดียว
const lightTopic = c => "scf/" + c.mqtt_user + "/node/" + c.node_id + "/light/set";
await run(async () => {
    if (msg.method !== "POST") throw fail(405, "method not allowed");

    if (R === "lights-off") {
        const fid = farmParam();
        need("light_all", fid);
        const targets = coops.filter(c => c.farm_id === fid && c.active && c.mqtt_user);
        if (!targets.length) throw fail(409, "ยังไม่มีโรงเรือนที่ผูกกับอุปกรณ์");
        // ตั้งเวลาไว้ = เลิกตั้งเวลา ไม่งั้นตัวตั้งเวลาจะเปิดกลับ
        const autoIds = targets.filter(c => c.light_mode === "auto").map(c => c.id);
        if (autoIds.length) {
            await scf.db.update("coops", "id=" + scf.inList(autoIds), { light_mode: "manual" });
            for (const c of targets) if (autoIds.includes(c.id)) c.light_mode = "manual";
        }
        await audit("lights_off_all", fid, { coops: targets.length, to_manual: autoIds.length || undefined });
        return done({ ok: true, coops: targets.map(c => c.id), to_manual: autoIds.length }, {
            mqtt: targets.map(c => ({ topic: lightTopic(c), payload: "OFF", retain: true, qos: 1 })),
            reload: autoIds.length > 0,
        });
    }

    const c = coopOf(b.coop_id);
    if (!c.active) throw fail(409, "โรงเรือนนี้ถูกปิดใช้งาน");

    if (R === "light") {
        need("light", c.farm_id, c.id);
        if (!c.mqtt_user) throw fail(409, "โรงเรือนนี้ยังไม่ได้ผูกกับอุปกรณ์ (ตั้งค่าที่หน้าจัดการฟาร์ม)");
        if (typeof b.on !== "boolean") throw fail(400, "ต้องระบุ on เป็น true/false");
        let toManual = false;
        if (c.light_mode === "auto") {           // กดเองระหว่างตั้งเวลา = เลิกตั้งเวลา ไม่งั้นตัวตั้งเวลาจะสั่งกลับ
            await scf.db.update("coops", "id=eq." + c.id, { light_mode: "manual" });
            c.light_mode = "manual";
            toManual = true;
        }
        await audit("light", c.farm_id, { coop_id: c.id, coop: c.name, on: b.on, to_manual: toManual || undefined });
        return done({ ok: true, to_manual: toManual }, {
            mqtt: { topic: lightTopic(c), payload: b.on ? "ON" : "OFF", retain: true, qos: 1 },
            reload: toManual,
        });
    }

    if (R === "settings") {
        need("coop_settings", c.farm_id, c.id);
        if (!["manual", "auto"].includes(b.light_mode)) throw fail(400, "โหมดไฟต้องเป็น manual หรือ auto");
        if (!isTime(b.light_on) || !isTime(b.light_off)) throw fail(400, "เวลาต้องเป็นรูปแบบ HH:MM");
        await scf.db.update("coops", "id=eq." + c.id, { light_mode: b.light_mode, light_on: b.light_on, light_off: b.light_off });
        await audit("light_schedule", c.farm_id, { coop_id: c.id, coop: c.name, mode: b.light_mode, on: b.light_on, off: b.light_off });
        return done({ ok: true }, { reload: true });
    }

    if (R === "flock") {
        need("flock", c.farm_id, c.id);
        const birds = Number(b.birds);
        if (!isDate(b.started_on) || b.started_on > todayStr) throw fail(400, "วันลงไก่ไม่ถูกต้อง (ห้ามเป็นวันในอนาคต)");
        if (!Number.isInteger(birds) || birds < 1 || birds > 1000000) throw fail(400, "จำนวนไก่ต้องเป็นจำนวนเต็ม 1–1,000,000");
        if (c.capacity && birds > c.capacity) throw fail(400, "เกินความจุโรงเรือน (" + c.capacity.toLocaleString() + " ตัว)");
        const breed = text(b.breed, 40, "สายพันธุ์", false);
        await scf.db.rpc("start_flock", { p_coop: c.id, p_started_on: b.started_on, p_birds: birds, p_breed: breed || "" });
        await audit("flock_start", c.farm_id, { coop_id: c.id, coop: c.name, started_on: b.started_on, birds, breed });
        return done({ ok: true }, { reload: true });
    }

    if (R === "flock-end") {
        need("flock", c.farm_id, c.id);
        if (!c.flock) throw fail(409, "โรงเรือนนี้ไม่มีรุ่นที่กำลังเลี้ยง");
        await scf.db.rpc("end_flock", { p_coop: c.id });
        await audit("flock_end", c.farm_id, { coop_id: c.id, coop: c.name, alive: c.flock.alive, age_days: c.flock.age_days });
        return done({ ok: true }, { reload: true });
    }

    if (R === "daily-log") {
        need("daily_log", c.farm_id, c.id);
        if (!c.flock || c.flock.id !== scf.int(b.flock_id)) throw fail(409, "รุ่นไก่ไม่ตรงกับปัจจุบัน ลองรีเฟรชหน้า");
        if (!isDate(b.log_date) || b.log_date > todayStr || b.log_date < c.flock.started_on) throw fail(400, "วันที่ต้องอยู่ระหว่างวันลงไก่ถึงวันนี้");
        const deaths = Number(b.deaths || 0), feed = Number(b.feed_kg || 0);
        const w = b.avg_weight_g === "" || b.avg_weight_g == null ? null : Number(b.avg_weight_g);
        if (!Number.isInteger(deaths) || deaths < 0 || deaths > c.flock.birds) throw fail(400, "จำนวนไก่ตายต้องเป็นจำนวนเต็ม 0 ถึงจำนวนที่ลง");
        if (!Number.isFinite(feed) || feed < 0 || feed > 100000) throw fail(400, "อาหารต้องเป็นตัวเลข 0–100,000 กก.");
        if (w !== null && !(w > 0 && w <= 10000)) throw fail(400, "น้ำหนักเฉลี่ยต้องอยู่ระหว่าง 1–10,000 กรัม");
        await scf.db.upsert("daily_logs", { flock_id: c.flock.id, coop_id: c.id, log_date: b.log_date, deaths, feed_kg: feed,
            avg_weight_g: w, note: text(b.note, 200, "หมายเหตุ", false), created_by: user.id }, "flock_id,log_date");
        await audit("daily_log", c.farm_id, { coop_id: c.id, coop: c.name, log_date: b.log_date, deaths, feed_kg: feed, avg_weight_g: w });
        return done({ ok: true }, { reload: true });
    }
    throw fail(404, "ไม่รู้จัก " + R);
});
return null;

