// POST: farm · farm-delete · coop · coop-delete · gateway · gateway-password
//   farm              ผู้ดูแลระบบ: เพิ่มฟาร์ม (พร้อม gateway + ผู้ดูแลฟาร์มคนแรก ในครั้งเดียว: ทุกฟาร์มมีคนดูแลตั้งแต่เกิด) / แก้ไข
//   farm-delete       ผู้ดูแลระบบ: ลบฟาร์มทั้งฟาร์ม (โรงเรือน+ประวัติ, gateway+บัญชี MQTT, ผู้ดูแล/ผู้ดูของฟาร์ม) ต้องพิมพ์ชื่อยืนยัน
//   coop              ผู้ดูแลฟาร์ม (ฟาร์มตัวเอง) หรือผู้ดูแลระบบ: เพิ่ม/แก้โรงเรือน + ผูกกับหมายเลขโหนดของ gateway
//                     เพิ่มใหม่ได้ครบในครั้งเดียว: เวลาไฟ และรุ่นไก่ (flock)
//   coop-delete       ผู้ดูแลระบบ: ลบโรงเรือนพร้อมประวัติทั้งหมด
//   gateway, gateway-password   ผู้ดูแลระบบ
//   board-kit         ค่าสำหรับแฟลชบอร์ดแบบพร้อมใช้ (หน้า "ตั้งค่าบอร์ด"): ตัวลูก = ผู้ดูแลฟาร์มขึ้นไป · ตัวแม่ (ออกรหัส MQTT ใหม่) = ผู้ดูแลระบบ
//                     โรงเรือนที่ยังไม่ผูกบอร์ดจะได้ NODE_ID ที่ว่างของ gateway นั้นให้อัตโนมัติ
// ตรวจทุกช่องก่อนเขียนอะไรลงฐานข้อมูล ถ้าขั้นหลังพลาดจะลบสิ่งที่เพิ่งสร้างทิ้ง
// MQTT username: gw<farm>-<n> unique, also the topic prefix scf/<username>/
const nextGwUser = fid => { let n = gateways.filter(g => g.farm_id === fid).length + 1, u; do { u = "gw" + fid + "-" + n++; } while (gateways.some(g => g.mqtt_user === u)); return u; };
// a new account checked completely before anything is written
// ชื่อผู้ใช้เว้นว่างได้: ระบบตั้งให้เองหลังรู้หมายเลขฟาร์ม (เช่น farm2.keeper1)
const newAccount = async (k, label) => {
    const username = String(k.username || "").trim().toLowerCase() || null;
    if (username && !/^[a-z0-9._-]{3,32}$/.test(username)) throw fail(400, "ชื่อผู้ใช้ของ" + label + "ใช้ a-z 0-9 . _ - ยาว 3–32 ตัว");
    if (username && (await scf.db.get("users?select=id&username=eq." + username)).length) throw fail(409, "ชื่อผู้ใช้ \"" + username + "\" มีคนใช้แล้ว");
    let password = k.password ? String(k.password) : null, generated = false;
    if (password) { const p = scf.passwordProblem(password); if (p) throw fail(400, p); }
    else { password = scf.randomPassword(10) + "7"; generated = true; }
    return { username, display_name: text(k.display_name, 60, "ชื่อ" + label), password, generated };
};

await run(async () => {
    if (msg.method !== "POST") throw fail(405, "method not allowed");

    if (R === "farm") {
        need("farm_manage", null);
        const row = { name: text(b.name, 80, "ชื่อฟาร์ม"), location: text(b.location, 120, "ที่ตั้ง", false) };
        if (b.id) {
            const f = farmOf(b.id);
            if (typeof b.active === "boolean") row.active = b.active;
            await scf.db.update("farms", "id=eq." + f.id, row);
            await audit("farm_update", f.id, row);
            return done({ ok: true, id: f.id }, { reload: true });
        }
        // ---- ฟาร์มใหม่ = ฟาร์ม + gateway + ผู้ดูแลฟาร์มคนแรก + โรงเรือน N หลัง (ผูกโหนด 1..N ของ gateway)
        const k = Object.assign({}, b.keeper || {});
        if (!String(k.display_name || "").trim()) k.display_name = ("ผู้ดูแล" + row.name).slice(0, 60);   // ไม่กรอก = ตั้งชื่อให้
        const keeper = await newAccount(k, "ผู้ดูแลฟาร์ม");
        const nCoops = b.coops == null || b.coops === "" ? 0 : Number(b.coops);
        if (!Number.isInteger(nCoops) || nCoops < 0 || nCoops > 20) throw fail(400, "จำนวนโรงเรือนต้องเป็น 0–20 หลัง (gateway 1 ตัวรองรับ 20 โรง)");
        const gwName = text(b.gateway_name, 60, "ชื่อ gateway", false) || "Gateway " + row.name.slice(0, 50);
        const farmKey = scf.randomHex(16);
        const f = (await scf.db.insert("farms", Object.assign({}, row, { farm_key: farmKey })))[0];
        let g = null;
        try {
            const mqttUser = nextGwUser(f.id);
            g = (await scf.db.insert("gateways", { farm_id: f.id, name: gwName, mqtt_user: mqttUser }))[0];
            if (!keeper.username) keeper.username = scf.nextUsername(scf.usernamePrefix("keeper", f.id), (await scf.db.get("users?select=username")).map(u => u.username));
            await scf.db.insert("users", { username: keeper.username, display_name: keeper.display_name, password_hash: scf.hashPassword(keeper.password),
                                           role: "keeper", farm_id: f.id, active: true });
            if (nCoops) await scf.db.insert("coops", Array.from({ length: nCoops }, (_, i) =>
                ({ farm_id: f.id, name: "โรงเรือน " + (i + 1), gateway_id: g.id, node_id: i + 1 })));
        } catch (e) {
            await scf.db.rpc("delete_farm", { p_farm: f.id }).catch(x => node.warn("rollback: " + x.message));   // ไม่เหลืออะไรค้าง
            throw e;
        }
        const password = scf.randomPassword(20);
        scf.mqttAccount("add", g.mqtt_user, password);
        await audit("farm_create", f.id, Object.assign({ gateway: g.mqtt_user, keeper: keeper.username, coops: nCoops }, row));
        return done({ ok: true, id: f.id, mqtt_user: g.mqtt_user, mqtt_password: password, farm_key: farmKey,
                      username: keeper.username, keeper_name: keeper.display_name, coops: nCoops,
                      temp_password: keeper.generated ? keeper.password : undefined }, { reload: true });
    }

    if (R === "farm-delete") {
        need("farm_manage", null);
        const f = farmOf(b.id);
        if (String(b.confirm || "").trim() !== f.name) throw fail(400, "พิมพ์ชื่อฟาร์มให้ตรงเพื่อยืนยันการลบ");
        const gws = gateways.filter(g => g.farm_id === f.id);
        const all = global.get("users") || {};
        const people = Object.values(all).filter(u => u.farm_id === f.id && u.role !== "admin");
        await scf.db.rpc("delete_farm", { p_farm: f.id });            // ทั้งหมดในครั้งเดียว: สำเร็จทั้งหมดหรือไม่เปลี่ยนอะไรเลย
        for (const g of gws) { try { scf.mqttAccount("del", g.mqtt_user); } catch (e) { node.warn("mqtt del " + g.mqtt_user + ": " + e.message); } }
        for (const u of people) delete all[u.id];                      // token และข้อมูลสดของคนในฟาร์มนี้หยุดทันที
        global.set("users", all);
        await audit("farm_delete", null, { farm: f.name, farm_id: f.id, coops: coops.filter(c => c.farm_id === f.id).length,
                                           gateways: gws.map(g => g.mqtt_user), users: people.map(u => u.username) });
        return done({ ok: true }, { reload: true });
    }

    if (R === "coop") {
        const existing = b.id ? coopOf(b.id) : null;
        const fid = existing ? existing.farm_id : farmParam();          // ย้ายโรงเรือนข้ามฟาร์มไม่ได้
        if (!fid) throw fail(400, "ต้องระบุฟาร์ม");
        need("coop_manage", fid);
        if (!farmOf(fid).active) throw fail(409, "ฟาร์มนี้ถูกปิดใช้งาน");
        const row = { farm_id: fid, name: text(b.name, 60, "ชื่อโรงเรือน") };
        const cap = b.capacity === "" || b.capacity == null ? null : Number(b.capacity);
        if (cap !== null && !(Number.isInteger(cap) && cap >= 1 && cap <= 1000000)) throw fail(400, "ความจุต้องเป็นจำนวนเต็ม 1–1,000,000");
        row.capacity = cap;
        const gid = b.gateway_id === "" || b.gateway_id == null ? null : scf.int(b.gateway_id);
        if (gid) {
            const g = gateways.find(g => g.id === gid);
            if (!g || g.farm_id !== fid) throw fail(400, "gateway ต้องเป็นของฟาร์มเดียวกัน");
            if (!g.active) throw fail(400, "gateway นี้ถูกปิดใช้งาน");
            const node = Number(b.node_id);
            if (!Number.isInteger(node) || node < 1 || node > 20) throw fail(400, "หมายเลขโหนดต้องเป็น 1–20 (ตรงกับ NODE_ID ในบอร์ดลูก)");
            const clash = coops.find(c => c.active && c.gateway_id === gid && c.node_id === node && (!existing || c.id !== existing.id));
            if (clash) throw fail(409, "โหนด " + node + " ใช้กับ \"" + clash.name + "\" อยู่แล้ว");
            row.gateway_id = gid; row.node_id = node;
        } else { row.gateway_id = null; row.node_id = null; }
        if (typeof b.active === "boolean") row.active = b.active;
        if (existing) {
            if (row.active === false && existing.active && existing.flock) throw fail(409, "จบรุ่นไก่ในโรงเรือนนี้ก่อนปิดใช้งาน");
            await scf.db.update("coops", "id=eq." + existing.id, row);
            await audit("coop_update", fid, Object.assign({ coop_id: existing.id }, row));
            return done({ ok: true, id: existing.id }, { reload: true });
        }

        // ---- เพิ่มใหม่: ตรวจรายละเอียดที่เหลือให้ครบก่อน
        const mode = b.light_mode || "manual";
        if (!["manual", "auto"].includes(mode)) throw fail(400, "โหมดไฟต้องเป็น manual หรือ auto");
        row.light_mode = mode;
        if (b.light_on != null || b.light_off != null) {
            if (!isTime(b.light_on) || !isTime(b.light_off)) throw fail(400, "เวลาเปิด-ปิดไฟต้องเป็นรูปแบบ HH:MM");
            row.light_on = b.light_on; row.light_off = b.light_off;
        }
        // ผู้ดูแลโรงเรือนของโรงใหม่ (ไม่บังคับ): ต้องเป็นผู้ดูแลโรงเรือนของฟาร์มนี้
        const allUsers = global.get("users") || {};
        const caretakers = [...new Set((Array.isArray(b.caretaker_ids) ? b.caretaker_ids : []).map(scf.int).filter(Boolean))].map(id => {
            const u = allUsers[id];
            if (!u || u.role !== "coop_keeper" || u.farm_id !== fid) throw fail(400, "ผู้ดูแลโรงเรือนที่เลือกต้องอยู่ในฟาร์มนี้");
            return u;
        });
        if (caretakers.length) need("staff_manage", fid);
        let flock = null;
        if (b.flock) {
            need("flock", fid);
            const birds = Number(b.flock.birds);
            if (!isDate(b.flock.started_on) || b.flock.started_on > todayStr) throw fail(400, "วันลงไก่ไม่ถูกต้อง (ห้ามเป็นวันในอนาคต)");
            if (!Number.isInteger(birds) || birds < 1 || birds > 1000000) throw fail(400, "จำนวนไก่ต้องเป็นจำนวนเต็ม 1–1,000,000");
            if (cap && birds > cap) throw fail(400, "จำนวนไก่เกินความจุโรงเรือน (" + cap.toLocaleString() + " ตัว)");
            flock = { started_on: b.flock.started_on, birds, breed: text(b.flock.breed, 40, "สายพันธุ์", false) || "" };
        }
        const c = (await scf.db.insert("coops", row))[0];
        try {
            if (flock) await scf.db.rpc("start_flock", { p_coop: c.id, p_started_on: flock.started_on, p_birds: flock.birds, p_breed: flock.breed });
        } catch (e) {
            await scf.db.rpc("delete_coop", { p_coop: c.id }).catch(x => node.warn("rollback: " + x.message));
            throw e;
        }
        if (caretakers.length) {
            try {
                await scf.db.insert("user_coops", caretakers.map(u => ({ user_id: u.id, coop_id: c.id })));
                for (const u of caretakers) u.coop_ids = [...(u.coop_ids || []), Number(c.id)];   // มีผลทันที
                global.set("users", allUsers);
            } catch (e) { node.warn("caretakers: " + e.message); }
        }
        await audit("coop_create", fid, Object.assign({ coop_id: c.id, flock: flock ? flock.birds : undefined,
            caretakers: caretakers.length ? caretakers.map(u => u.username) : undefined }, row));
        return done({ ok: true, id: c.id }, { reload: true });
    }

    if (R === "coop-delete") {
        const c = coopOf(b.id);
        need("coop_delete", c.farm_id);
        if (String(b.confirm || "").trim() !== c.name) throw fail(400, "พิมพ์ชื่อโรงเรือนให้ตรงเพื่อยืนยันการลบ");
        await scf.db.rpc("delete_coop", { p_coop: c.id });
        await audit("coop_delete", c.farm_id, { coop_id: c.id, coop: c.name, had_flock: !!c.flock || undefined });
        return done({ ok: true }, { reload: true });
    }

    if (R === "gateway") {
        need("gateway_manage", null);
        if (b.id) {
            const g = gateways.find(g => g.id === scf.int(b.id));
            if (!g) throw fail(404, "ไม่พบ gateway");
            const row = { name: text(b.name, 60, "ชื่อ gateway") };
            if (typeof b.active === "boolean") row.active = b.active;
            await scf.db.update("gateways", "id=eq." + g.id, row);
            if (row.active === false && g.active) scf.mqttAccount("del", g.mqtt_user);   // ตัดสิทธิ์ MQTT ทันที
            await audit("gateway_update", g.farm_id, Object.assign({ gateway: g.mqtt_user }, row));
            return done({ ok: true, id: g.id }, { reload: true });
        }
        const fid = farmOf(b.farm_id).id;
        if (!farmOf(fid).active) throw fail(409, "ฟาร์มนี้ถูกปิดใช้งาน");
        const mqttUser = nextGwUser(fid);
        const g = (await scf.db.insert("gateways", { farm_id: fid, name: text(b.name, 60, "ชื่อ gateway"), mqtt_user: mqttUser }))[0];
        const password = scf.randomPassword(20);
        scf.mqttAccount("add", mqttUser, password);
        await audit("gateway_create", fid, { gateway: mqttUser });
        const fk = ((await scf.db.get("farms?select=farm_key&id=eq." + fid))[0] || {}).farm_key || null;
        return done({ ok: true, id: g.id, mqtt_user: mqttUser, mqtt_password: password, farm_key: fk }, { reload: true });
    }

    if (R === "board-kit") {
        const g = gateways.find(g => g.id === scf.int(b.gateway_id));
        if (!g || !scf.seesFarm(user, g.farm_id)) throw fail(404, "ไม่พบ gateway");
        const fid = g.farm_id;
        need("coop_manage", fid);
        if (!g.active) throw fail(409, "gateway นี้ถูกปิดใช้งาน: เปิดใช้งานก่อน");
        const withGw = b.gateway === true;
        if (withGw) need("gateway_manage", fid);
        // กุญแจฟาร์ม: เก็บไว้ในฐานข้อมูล · ยังไม่มี = สร้างได้เฉพาะตอนแฟลชตัวแม่ด้วย (ไม่งั้นตัวแม่กับตัวลูกกุญแจไม่ตรงกัน)
        let key = ((await scf.db.get("farms?select=farm_key&id=eq." + fid))[0] || {}).farm_key || null, newKey = false;
        if (!key && !withGw) throw fail(409, "ฟาร์มนี้ยังไม่มีกุญแจฟาร์มในระบบ: ครั้งแรกต้องแฟลชตัวแม่พร้อมกัน (ผู้ดูแลระบบเลือก \"ตัวแม่\" ด้วย)");
        // โรงเรือนที่เลือก: ต้องอยู่ในฟาร์มนี้ · ยังไม่ผูกบอร์ด = ได้ NODE_ID ที่ว่างของ gateway นี้
        const farmCoops = coops.filter(c => c.farm_id === fid && c.active);
        const chosen = [...new Set((Array.isArray(b.coop_ids) ? b.coop_ids : []).map(scf.int).filter(Boolean))].map(id => {
            const c = farmCoops.find(c => c.id === id);
            if (!c) throw fail(400, "โรงเรือนที่เลือกต้องอยู่ในฟาร์มนี้และใช้งานอยู่");
            if (c.gateway_id && c.gateway_id !== g.id) throw fail(400, c.name + " ผูกกับ gateway อื่นอยู่: เลือก gateway นั้นแทน");
            return c;
        });
        if (!withGw && !chosen.length) throw fail(400, "เลือกตัวแม่ หรือโรงเรือนอย่างน้อย 1 โรง");
        const used = new Set(farmCoops.filter(c => c.gateway_id === g.id).map(c => c.node_id));
        const free = chosen.filter(c => !c.gateway_id);
        const nodeOf = {};
        for (const c of free) {
            let n = 1; while (used.has(n)) n++;
            if (n > 20) throw fail(409, "gateway นี้มีบอร์ดลูกครบ 20 ตัวแล้ว: เพิ่ม gateway อีกตัว");
            used.add(n); nodeOf[c.id] = n;
        }
        for (const c of free) await scf.db.update("coops", "id=eq." + c.id, { gateway_id: g.id, node_id: nodeOf[c.id] });
        if (!key) { key = scf.randomHex(16); await scf.db.update("farms", "id=eq." + fid, { farm_key: key }); newKey = true; }
        let src;
        try { src = scf.firmwareSources(); }
        catch (e) { throw fail(500, "อ่านไฟล์ firmware ไม่ได้: รัน start.sh ใหม่ (docker-compose.yml ต้องมี ./firmware:/firmware:ro)"); }
        let mqttPassword = null;
        if (withGw) { mqttPassword = scf.randomPassword(20); scf.mqttAccount("add", g.mqtt_user, mqttPassword); }   // รหัสเดิมใช้ไม่ได้ทันที
        // ที่อยู่ server สำหรับตัวแม่: IP ใน Wi-Fi จาก start.sh หรือชื่อเครื่องที่เปิดเว็บอยู่
        const ip = String(env.get("SERVER_IP") || ""), reqHost = String((msg.req && msg.req.headers && msg.req.headers.host) || "").split(":")[0];
        const host = /^[0-9.]{7,15}$/.test(ip) ? ip : (reqHost && !/^(localhost|127\.0\.0\.1)$/.test(reqHost) ? reqHost : null);
        const nodes = chosen.map(c => ({ coop_id: c.id, coop: c.name, node_id: c.gateway_id ? c.node_id : nodeOf[c.id] }));
        await audit("board_kit", fid, { gateway: g.mqtt_user, new_mqtt_password: withGw || undefined, new_farm_key: newKey || undefined,
            nodes: nodes.map(x => x.node_id), bound: free.length || undefined });
        return done({ ok: true, farm_id: fid, gateway: { id: g.id, name: g.name, mqtt_user: g.mqtt_user, mqtt_password: mqttPassword },
            farm_key: key, new_farm_key: newKey, mqtt_host: host, mqtt_port: 1883, nodes, sources: src }, { reload: free.length > 0 });
    }

    if (R === "gateway-password") {
        need("gateway_manage", null);
        const g = gateways.find(g => g.id === scf.int(b.id));
        if (!g) throw fail(404, "ไม่พบ gateway");
        if (!g.active) throw fail(409, "เปิดใช้งาน gateway ก่อน");
        const password = scf.randomPassword(20);
        scf.mqttAccount("add", g.mqtt_user, password);     // add = เขียนทับรหัสเดิม
        const newKey = b.new_farm_key ? scf.randomHex(16) : null;
        if (newKey) await scf.db.update("farms", "id=eq." + g.farm_id, { farm_key: newKey });   // บอร์ดทุกตัวในฟาร์มต้องแฟลชใหม่
        await audit("gateway_password", g.farm_id, { gateway: g.mqtt_user, new_farm_key: !!b.new_farm_key });
        return done({ ok: true, id: g.id, mqtt_user: g.mqtt_user, mqtt_password: password, farm_key: newKey });
    }
    throw fail(404, "ไม่รู้จัก " + R);
});
return null;

// ---- ส่วนกลางของทุก API (ตรวจสิทธิ์ + ตัวช่วย) ----
const scf = global.get("scf");
const user = msg.user, q = msg.q, b = msg.body, R = msg.resource;
const farms = global.get("farms") || [], coops = global.get("coops") || [], gateways = global.get("gateways") || [];
const isAdmin = user.role === "admin";
const fail = scf.fail;
// สิทธิ์: ไม่ผ่าน = 403 ทันที (ผู้ใช้ที่ไม่ใช่ admin ทำได้เฉพาะในฟาร์มของตัวเอง · ผู้ดูแลโรงเรือนเฉพาะโรงเรือนของตัวเอง)
const need = (perm, farmId, coopId) => { if (!scf.can(user, perm, farmId, coopId)) throw fail(403, "คุณไม่มีสิทธิ์ทำรายการนี้"); };
// ฟาร์มที่คำขอนี้หมายถึง: admin เลือกได้ (ไม่ระบุ = ฟาร์มแรกที่เปิดใช้งาน), คนอื่นได้ฟาร์มตัวเองเท่านั้น (ขอฟาร์มอื่น = 403)
const farmParam = () => {
    const asked = scf.int(q.farm_id != null ? q.farm_id : b.farm_id);
    if (!isAdmin) {
        if (asked && asked !== user.farm_id) throw fail(403, "คุณเข้าถึงได้เฉพาะฟาร์มของตัวเอง");
        return user.farm_id;
    }
    return asked || (farms.find(f => f.active) || farms[0] || {}).id || null;
};
const farmOf = id => { const f = farms.find(f => f.id === scf.int(id)); if (!f || !scf.seesFarm(user, f.id)) throw fail(404, "ไม่พบฟาร์ม"); return f; };
// โรงเรือนในฟาร์มอื่น (หรือที่ผู้ดูแลโรงเรือนไม่ได้ดูแล) ตอบว่า "ไม่พบ" (ไม่บอกว่ามีอยู่)
const coopOf = id => { const c = coops.find(c => c.id === scf.int(id)); if (!c || !scf.seesCoop(user, c)) throw fail(404, "ไม่พบโรงเรือน"); return c; };
const text = (v, max, label, required = true) => {
    const s = String(v == null ? "" : v).trim();
    if (required && !s) throw fail(400, "กรุณากรอก" + label);
    if (s.length > max) throw fail(400, label + "ยาวเกิน " + max + " ตัวอักษร");
    return s || null;
};
const isDate = s => /^\d{4}-\d{2}-\d{2}$/.test(String(s)) && !isNaN(Date.parse(s));
const isTime = s => /^([01]\d|2[0-3]):[0-5]\d$/.test(String(s));
const pad = n => String(n).padStart(2, "0");
const todayStr = (() => { const d = new Date(); return d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate()); })();
const since = () => q.since && !isNaN(Date.parse(q.since)) ? new Date(q.since).toISOString() : null;
const limit = (d, max = 1000) => Math.min(Math.max(parseInt(q.limit, 10) || d, 1), max);
const audit = (action, farmId, detail) => scf.db.insert("audit_log", {
    user_id: user.id, username: user.username, farm_id: farmId == null ? null : farmId, action, detail: detail == null ? null : detail,
}).catch(e => node.warn("audit: " + e.message));
// outputs: 1 ตอบเว็บ, 2 MQTT (คำสั่งไฟ), 3 โหลดข้อมูลฟาร์มใหม่, 4 ส่งข้อมูลสด
const done = (body, extra = {}) => { node.send([scf.reply(msg, 200, body), extra.mqtt || null, extra.reload ? { payload: "reload" } : null, extra.live || null]); };
const run = async fn => {
    try { await fn(); }
    catch (e) {
        if (!e.http && e.code !== "23505") node.error(R + ": " + e.message);
        node.send([scf.errorReply(msg, e), null, null, null]);
    }
};
// ---- จบส่วนกลาง ----

// users (GET) · user (POST สร้าง/แก้) · user-delete (POST ลบ) · user-password (POST รีเซ็ต) · password (POST เปลี่ยนรหัสตัวเอง)
// กติกา:
//   - ผู้ดูแลระบบ: จัดการบัญชีได้ทุกบทบาททุกฟาร์ม
//   - ผู้ดูแลฟาร์ม: เพิ่ม/แก้/ลบ/รีเซ็ตรหัส "ผู้ดูแลโรงเรือน" ของฟาร์มตัวเองเท่านั้น (บทบาทอื่นดูได้อย่างเดียว)
//   - ผู้ดูแลโรงเรือนต้องได้รับโรงเรือนอย่างน้อย 1 หลัง และเป็นโรงเรือนในฟาร์มเดียวกันเท่านั้น (ฐานข้อมูลตรวจซ้ำ: user_coops)
//   - ผู้ใช้ที่ไม่ใช่ admin อยู่ได้ฟาร์มเดียว (ฐานข้อมูลบังคับซ้ำอีกชั้น: users_one_farm)
//   - ทุกฟาร์มต้องมีผู้ดูแลฟาร์มที่ใช้งานได้อย่างน้อย 1 คน: ลบ/ปิด/ย้าย/ลดสิทธิ์คนสุดท้ายไม่ได้
//   - ห้ามแก้สิทธิ์/ฟาร์ม/ปิด/ลบบัญชีตัวเอง, ห้ามทำให้ไม่มี admin เหลือ
//   - เปลี่ยนสิทธิ์/ฟาร์ม/สถานะ/รหัส หรือลบ = token เดิมของคนนั้นใช้ไม่ได้ทันที
await run(async () => {
    const all = global.get("users") || {};
    const COLS = "id,username,display_name,role,farm_id,active,session_version,last_login,locked_until,totp_enabled";
    const fresh = async id => (await scf.db.get("users?select=" + COLS + "&id=eq." + id))[0];
    const countActive = async filter => (await scf.db.get("users?select=id&active=eq.true&" + filter)).length;
    // t = บัญชีก่อนแก้: ถ้าเป็นผู้ดูแลฟาร์มคนสุดท้ายของฟาร์มและกำลังจะไม่ใช่ -> ห้าม
    const keepLastKeeper = async (t, stillKeeperThere) => {
        if (t.role === "keeper" && t.active && !stillKeeperThere && await countActive("role=eq.keeper&farm_id=eq." + t.farm_id) <= 1) {
            const f = farms.find(f => f.id === t.farm_id);
            throw fail(409, (f ? f.name : "ฟาร์มนี้") + " ต้องมีผู้ดูแลฟาร์มอย่างน้อย 1 คน: เพิ่มผู้ดูแลคนใหม่ก่อน");
        }
    };
    const keepLastAdmin = async (t, stillAdmin) => {
        if (t.role === "admin" && t.active && !stillAdmin && await countActive("role=eq.admin") <= 1) throw fail(409, "ต้องมีผู้ดูแลระบบที่ใช้งานได้อย่างน้อย 1 คน");
    };
    // ผู้ดูแลฟาร์มจัดการได้เฉพาะผู้ดูแลโรงเรือนในฟาร์มตัวเอง · admin จัดการได้ทุกคน
    const manages = t => isAdmin ? scf.can(user, "users_manage", null)
        : !!t && t.role === "coop_keeper" && scf.can(user, "staff_manage", t.farm_id);
    const needManage = t => { if (!manages(t)) throw fail(403, "คุณจัดการได้เฉพาะบัญชีผู้ดูแลโรงเรือนในฟาร์มของคุณ"); };
    // โรงเรือนที่มอบให้ผู้ดูแลโรงเรือน: อย่างน้อย 1 หลัง ทุกหลังอยู่ในฟาร์มนั้น
    const coopList = (ids, farmId) => {
        const list = [...new Set((Array.isArray(ids) ? ids : []).map(scf.int).filter(Boolean))];
        if (!list.length) throw fail(400, "เลือกโรงเรือนที่ผู้ดูแลโรงเรือนคนนี้ดูแลอย่างน้อย 1 หลัง");
        if (list.length > 200) throw fail(400, "เลือกโรงเรือนได้ไม่เกิน 200 หลัง");
        for (const id of list) {
            const c = coops.find(c => c.id === id);
            if (!c || c.farm_id !== farmId) throw fail(400, "โรงเรือนที่เลือกต้องอยู่ในฟาร์มเดียวกับผู้ดูแล");
        }
        return list;
    };
    const saveCoops = async (uid, ids) => {
        await scf.db.del("user_coops", "user_id=eq." + uid);
        if (ids && ids.length) await scf.db.insert("user_coops", ids.map(coop_id => ({ user_id: uid, coop_id })));
    };
    const coopNames = ids => (ids || []).map(id => (coops.find(c => c.id === id) || {}).name).filter(Boolean);

    if (R === "users") {
        if (msg.method !== "GET") throw fail(405, "method not allowed");
        if (!scf.can(user, "users_manage", null) && !scf.can(user, "staff_manage", user.farm_id)) throw fail(403, "คุณไม่มีสิทธิ์ทำรายการนี้");
        const fid = isAdmin && q.all ? null : farmParam();
        const list = Object.values(all).filter(u => !fid || u.farm_id === fid || (isAdmin && u.role === "admin"));
        return done(list.map(u => Object.assign(scf.publicUser(u), { editable: u.id !== user.id && manages(u), self: u.id === user.id,
            coops: u.role === "coop_keeper" ? coopNames(scf.coopIdsOf(u)) : undefined })));
    }
    if (msg.method !== "POST") throw fail(405, "method not allowed");

    if (R === "password") {                                 // เปลี่ยนรหัสผ่านของตัวเอง
        const me = (await scf.db.get("users?select=id,password_hash,session_version&id=eq." + user.id))[0];
        if (!scf.verifyPassword(String(b.old_password || ""), me.password_hash)) throw fail(400, "รหัสผ่านเดิมไม่ถูกต้อง");
        const problem = scf.passwordProblem(b.new_password);
        if (problem) throw fail(400, problem);
        if (b.new_password === b.old_password) throw fail(400, "รหัสผ่านใหม่ต้องไม่ซ้ำกับรหัสเดิม");
        const sv = (me.session_version || 0) + 1;
        await scf.db.update("users", "id=eq." + user.id, { password_hash: scf.hashPassword(b.new_password), session_version: sv });
        all[user.id] = Object.assign({}, all[user.id], { session_version: sv }); global.set("users", all);
        await audit("password_change", user.farm_id, null);
        return done({ ok: true, token: scf.signToken({ id: user.id, session_version: sv }) }, { reload: true });   // เครื่องอื่นต้อง login ใหม่
    }

    // ---- ยืนยันตัวตน 2 ขั้นของตัวเอง: setup -> enable (รหัสจากแอป) · backup (รหัสสำรองชุดใหม่) · disable (เฉพาะบทบาทที่ไม่บังคับ)
    if (R === "mfa") {
        const me = (await scf.db.get("users?select=*&id=eq." + user.id))[0];
        const act = String(b.action || "");
        const okCode = secret => {
            const c = String(b.code || "").trim();
            if (/^[0-9\s]{6,7}$/.test(c)) return scf.verifyTotp(secret, c, me.totp_enabled ? me.totp_last_step : null);
            return null;
        };
        if (act === "setup") {
            if (me.totp_enabled) throw fail(409, "เปิดใช้อยู่แล้ว");
            const secret = scf.newTotpSecret();
            await scf.db.update("users", "id=eq." + me.id, { totp_secret: scf.sealSecret(secret), totp_enabled: false, totp_last_step: null });
            return done({ ok: true, secret, otpauth: scf.otpauthUrl(me.username, secret) });
        }
        const secret = scf.openSecret(me.totp_secret);
        if (!secret) throw fail(409, "ยังไม่ได้ตั้งค่า: เริ่มใหม่อีกครั้ง");
        const step = okCode(secret);
        if (step === null) throw fail(400, "รหัส 6 หลักไม่ถูกต้อง: ดูรหัสล่าสุดในแอปแล้วลองใหม่");
        if (act === "enable" || act === "backup") {
            if (act === "backup" && !me.totp_enabled) throw fail(409, "ยังไม่ได้เปิดใช้");
            const bc = scf.newBackupCodes();
            await scf.db.update("users", "id=eq." + me.id, { totp_enabled: true, totp_last_step: step, mfa_backup: bc.hashes });
            const all = global.get("users") || {}; if (all[me.id]) { all[me.id].totp_enabled = true; global.set("users", all); }
            await audit(act === "enable" ? "mfa_enable" : "mfa_backup_codes", me.farm_id, null);
            return done({ ok: true, backup_codes: bc.codes });
        }
        if (act === "disable") {
            if (scf.mfaRequired(me)) throw fail(403, "บทบาทนี้ต้องใช้ยืนยันตัวตน 2 ขั้นเสมอ");
            if (!scf.verifyPassword(String(b.password || ""), me.password_hash)) throw fail(400, "รหัสผ่านไม่ถูกต้อง");
            await scf.db.update("users", "id=eq." + me.id, { totp_secret: null, totp_enabled: false, totp_last_step: null, mfa_backup: null });
            const all = global.get("users") || {}; if (all[me.id]) { all[me.id].totp_enabled = false; global.set("users", all); }
            await audit("mfa_disable", me.farm_id, null);
            return done({ ok: true });
        }
        throw fail(400, "action ไม่ถูกต้อง");
    }

    if (R === "user-mfa-reset") {                           // ทำมือถือหาย: ล้างการตั้งค่า เข้าครั้งหน้าตั้งใหม่ (และออกจากระบบทุกเครื่อง)
        const t = await fresh(scf.int(b.id));
        if (!t) throw fail(404, "ไม่พบผู้ใช้");
        if (t.id === user.id) throw fail(400, "ปิด/ตั้งค่าของตัวเองที่เมนูบัญชี");
        needManage(t);
        const sv = (t.session_version || 0) + 1;
        await scf.db.update("users", "id=eq." + t.id, { totp_secret: null, totp_enabled: false, totp_last_step: null, mfa_backup: null, session_version: sv });
        all[t.id] = Object.assign({}, all[t.id] || t, { totp_enabled: false, session_version: sv }); global.set("users", all);
        await audit("mfa_reset", t.farm_id, { target: t.username });
        return done({ ok: true }, { reload: true });
    }

    if (R === "user-delete") {
        const t = await fresh(scf.int(b.id));
        if (!t) throw fail(404, "ไม่พบผู้ใช้");
        if (t.id === user.id) throw fail(400, "ลบบัญชีของตัวเองไม่ได้");
        needManage(t);
        await keepLastAdmin(t, false);
        await keepLastKeeper(t, false);
        await scf.db.del("users", "id=eq." + t.id);           // user_coops หายตาม (on delete cascade)
        delete all[t.id]; global.set("users", all);           // token และข้อมูลสดของคนนั้นหยุดทันที
        await audit("user_delete", t.farm_id, { target: t.username, role: t.role });
        return done({ ok: true }, { reload: true });
    }

    if (R === "user-password") {                            // รีเซ็ตรหัสให้คนอื่น -> รหัสชั่วคราว แสดงครั้งเดียว
        const t = await fresh(scf.int(b.id));
        if (!t) throw fail(404, "ไม่พบผู้ใช้");
        if (t.id === user.id) throw fail(400, "เปลี่ยนรหัสของตัวเองที่เมนู \"เปลี่ยนรหัสผ่าน\"");
        needManage(t);
        const temp = scf.randomPassword(10) + "7";
        const sv = (t.session_version || 0) + 1;
        await scf.db.update("users", "id=eq." + t.id, { password_hash: scf.hashPassword(temp), session_version: sv, failed_logins: 0, locked_until: null });
        all[t.id] = Object.assign({}, all[t.id] || t, { session_version: sv }); global.set("users", all);
        await audit("user_password_reset", t.farm_id, { target: t.username });
        return done({ ok: true, username: t.username, temp_password: temp }, { reload: true });
    }

    if (R === "user") {
        if (scf.int(b.id) === user.id) {                     // แก้บัญชีตัวเอง: ได้แค่ชื่อที่แสดง
            if ((b.role && b.role !== user.role) || b.active === false || (b.farm_id != null && scf.int(b.farm_id) !== (user.farm_id || null)) || b.coop_ids !== undefined)
                throw fail(400, "แก้สิทธิ์ ฟาร์ม โรงเรือน หรือปิดบัญชีของตัวเองไม่ได้");
            const display_name = text(b.display_name, 60, "ชื่อที่แสดง");
            await scf.db.update("users", "id=eq." + user.id, { display_name });
            all[user.id] = Object.assign({}, all[user.id], { display_name }); global.set("users", all);
            await audit("user_update", user.farm_id, { target: user.username, display_name });
            return done({ ok: true, id: user.id }, { reload: true });
        }
        const role = String(b.role || "");
        if (!scf.ROLES[role]) throw fail(400, "บทบาทไม่ถูกต้อง");
        // ผู้ดูแลฟาร์ม: บทบาทต้องเป็นผู้ดูแลโรงเรือน และอยู่ฟาร์มตัวเองเสมอ
        if (!isAdmin) {
            if (!scf.can(user, "staff_manage", user.farm_id)) throw fail(403, "คุณไม่มีสิทธิ์ทำรายการนี้");
            if (role !== "coop_keeper") throw fail(403, "ผู้ดูแลฟาร์มเพิ่ม/แก้ได้เฉพาะบัญชีผู้ดูแลโรงเรือน");
            if (b.farm_id != null && scf.int(b.farm_id) !== user.farm_id) throw fail(403, "คุณเข้าถึงได้เฉพาะฟาร์มของตัวเอง");
        } else need("users_manage", null);
        let farmId = null;
        if (role !== "admin") {
            const f = farms.find(f => f.id === (isAdmin ? scf.int(b.farm_id) : user.farm_id));
            if (!f) throw fail(400, "ผู้ใช้ที่ไม่ใช่ผู้ดูแลระบบต้องสังกัดฟาร์ม 1 ฟาร์ม");
            if (!f.active) throw fail(409, "ฟาร์มนี้ถูกปิดใช้งาน");
            farmId = f.id;
        }
        const coopIds = role === "coop_keeper" ? coopList(b.coop_ids, farmId) : null;
        const display = text(b.display_name, 60, "ชื่อที่แสดง");
        const active = b.active !== false;

        if (!b.id) {                                         // ---- สร้างบัญชีใหม่
            // เว้นว่าง = ระบบตั้งให้ เช่น farm2.coop3
            const username = String(b.username || "").trim().toLowerCase()
                || scf.nextUsername(scf.usernamePrefix(role, farmId), (await scf.db.get("users?select=username")).map(u => u.username));
            if (!/^[a-z0-9._-]{3,32}$/.test(username)) throw fail(400, "ชื่อผู้ใช้ใช้ a-z 0-9 . _ - ยาว 3–32 ตัว");
            let password = b.password ? String(b.password) : null, generated = false;
            if (password) { const p = scf.passwordProblem(password); if (p) throw fail(400, p); }
            else { password = scf.randomPassword(10) + "7"; generated = true; }
            const u = (await scf.db.insert("users", { username, display_name: display, password_hash: scf.hashPassword(password), role, farm_id: farmId, active }))[0];
            if (coopIds) {
                try { await saveCoops(u.id, coopIds); }
                catch (e) { await scf.db.del("users", "id=eq." + u.id).catch(x => node.warn("rollback: " + x.message)); throw e; }
            }
            all[u.id] = Object.assign({}, u, { coop_ids: coopIds || [] }); global.set("users", all);
            await audit("user_create", farmId, { target: username, role, coops: coopIds ? coopNames(coopIds) : undefined });
            return done({ ok: true, id: u.id, username, temp_password: generated ? password : undefined }, { reload: true });
        }

        // ---- แก้บัญชีเดิม
        const t = await fresh(scf.int(b.id));
        if (!t) throw fail(404, "ไม่พบผู้ใช้");
        needManage(t);
        const changes = { display_name: display, role, farm_id: farmId, active };
        if (role !== t.role || farmId !== (t.farm_id || null) || active !== t.active) changes.session_version = (t.session_version || 0) + 1;
        await keepLastAdmin(t, role === "admin" && active);
        await keepLastKeeper(t, role === "keeper" && active && farmId === t.farm_id);
        await scf.db.update("users", "id=eq." + t.id, changes);   // ไม่ใช่ผู้ดูแลโรงเรือนแล้ว/ย้ายฟาร์ม -> ฐานข้อมูลล้างโรงเรือนเดิมให้เอง
        if (coopIds) await saveCoops(t.id, coopIds);
        all[t.id] = Object.assign({}, t, changes, { coop_ids: coopIds || [] }); global.set("users", all);   // มีผลกับ token ทันที ไม่ต้องรอโหลดใหม่
        await audit("user_update", farmId != null ? farmId : t.farm_id, { target: t.username, role, farm_id: farmId, active,
            coops: coopIds ? coopNames(coopIds) : undefined });
        return done({ ok: true, id: t.id }, { reload: true });
    }
    throw fail(404, "ไม่รู้จัก " + R);
});
return null;

// แยกคำขอตามหมวด (แต่ละหมวดตรวจสิทธิ์ของตัวเองอีกชั้น)
const map = { "me": 0, "farms": 0, "farm-data": 0, "readings": 0, "led-events": 0, "alerts": 0, "daily-logs": 0, "audit": 0,
              "light": 1, "lights-off": 1, "settings": 1, "flock": 1, "flock-end": 1, "daily-log": 1,
              "farm": 2, "farm-delete": 2, "coop": 2, "coop-delete": 2, "gateway": 2, "gateway-password": 2, "board-kit": 2,
              "users": 3, "user": 3, "mfa": 3, "user-mfa-reset": 3, "user-delete": 3, "user-password": 3, "password": 3 };
const i = map[msg.resource];
const out = [null, null, null, null, null];
if (i === undefined) out[4] = global.get("scf").reply(msg, 404, { error: "ไม่รู้จัก " + msg.resource });
else out[i] = msg;
return out;

// ทุกคำขอ /api/* (ยกเว้น login): ตรวจ token -> หาผู้ใช้ -> ยังใช้งานได้ไหม -> ส่งต่อพร้อม msg.user
// token ใช้ไม่ได้ทันทีเมื่อ: ลายเซ็นผิด, หมดอายุ, บัญชีถูกปิด, เปลี่ยนรหัส/สิทธิ์/ฟาร์ม (session_version เปลี่ยน), ฟาร์มถูกปิด
// outputs: 1 ผ่าน, 2 ไม่ผ่าน (ตอบกลับทันที)
const scf = global.get("scf");
if (!global.get("cacheReady")) return [null, scf.reply(msg, 503, { error: "ระบบกำลังเริ่มทำงาน ลองใหม่อีกครั้ง" })];
const p = scf.verifyToken(scf.bearer(msg.req));
const u = p && (global.get("users") || {})[p.uid];
if (!p || !u || !u.active || (u.session_version || 0) !== p.sv) {
    return [null, scf.reply(msg, 401, { error: "กรุณาเข้าสู่ระบบใหม่", code: "auth" })];
}
if (u.role !== "admin") {
    const farm = (global.get("farms") || []).find(f => f.id === u.farm_id);
    if (!farm || !farm.active) return [null, scf.reply(msg, 403, { error: "ฟาร์มของคุณถูกปิดใช้งาน", code: "auth" })];
}
msg.user = u;
msg.resource = msg.req.params.resource;
msg.method = msg.req.method;
msg.q = msg.req.query || {};
msg.body = (msg.method === "POST" && msg.payload && typeof msg.payload === "object") ? msg.payload : {};
return [msg, null];

// GET /health: บอกแค่ว่าระบบพร้อมไหม (ใช้โดย start.sh) ไม่มีข้อมูลฟาร์ม
const ready = !!global.get("cacheReady");
msg.statusCode = ready ? 200 : 503;
msg.headers = { "Content-Type": "application/json", "Cache-Control": "no-store" };
msg.payload = JSON.stringify({ ok: ready });
return msg;

// จำลองบอร์ด: ส่งค่าให้ทุกโรงเรือนที่ผูกกับ gateway แล้ว (ทุกฟาร์ม) ใช้ตอนไม่มีบอร์ดจริง
const out = [];
for (const c of global.get("coops") || []) {
    if (!c.active || !c.mqtt_user) continue;
    const base = c.target.temp_ideal || 27;
    const t = base + Math.sin(Date.now() / 60000 + c.id) * 2.5 + (Math.random() - .5);
    const h = 62 + Math.cos(Date.now() / 90000 + c.id) * 6 + (Math.random() - .5) * 2;
    out.push({ topic: "scf/" + c.mqtt_user + "/node/" + c.node_id + "/telemetry", payload: { temp: +t.toFixed(2), humidity: +h.toFixed(2) } });
}
const gws = [...new Set((global.get("gateways") || []).filter(g => g.active).map(g => g.mqtt_user))];
for (const g of gws) out.push({ topic: "scf/" + g + "/status", payload: "online", retain: true });
return [out];

// จำลองโหนด: รับ light/set แล้วตอบ light/state กลับ (เหมือน ACK จากบอร์ดจริง)
const m = /^scf\/(gw[a-z0-9-]{1,30})\/node\/([0-9]{1,2})\/light\/set$/.exec(msg.topic);
if (!m) return null;
const on = String(msg.payload).trim().toUpperCase() === "ON";
return { topic: "scf/" + m[1] + "/node/" + m[2] + "/light/state", payload: on ? "ON" : "OFF", retain: true };

// POST /auth/mfa {mfa_token, code}: ขั้นที่ 2 ของการเข้าสู่ระบบ
// - code = รหัส 6 หลักจากแอป Authenticator (ยอมเวลาคลาดเคลื่อน ±30 วิ, ใช้รหัสเดิมซ้ำไม่ได้) หรือรหัสสำรอง ABCD-EFGH (ใช้ได้ครั้งเดียว)
// - ผิดนับรวมกับรหัสผ่าน: 5 ครั้งล็อก 5 นาที · IP เดียวผิดเกิน 20 ครั้ง/10 นาที บล็อก
// - ตั้งค่าครั้งแรก: รหัสแรกที่ถูก = เปิดใช้ + ได้รหัสสำรอง 8 ชุด (แสดงครั้งเดียว)
const scf = global.get("scf");
const b = (msg.payload && typeof msg.payload === "object") ? msg.payload : {};
const ip = String((msg.req.headers && msg.req.headers["x-forwarded-for"]) || msg.req.ip || "").split(",")[0].trim();
const ipKey = "ipfail_" + ip;
let rec = flow.get(ipKey) || { n: 0, t: Date.now() };
if (Date.now() - rec.t > 10 * 60000) rec = { n: 0, t: Date.now() };
if (rec.n >= 20) return scf.reply(msg, 429, { error: "ลองผิดหลายครั้งเกินไป กรุณารอ 10 นาที" });
const audit = (action, u, detail) => scf.db.insert("audit_log", { user_id: u.id, username: u.username, farm_id: u.farm_id, action, detail })
    .catch(e => node.warn("audit: " + e.message));
const expired = () => scf.reply(msg, 401, { error: "หมดเวลายืนยันตัวตน กรุณาเข้าสู่ระบบใหม่", code: "mfa_expired" });
try {
    const p = scf.verifyToken(b.mfa_token, "mfa");
    if (!p) return expired();
    const u = (await scf.db.get("users?select=*&id=eq." + p.uid))[0];
    if (!u || !u.active || (u.session_version || 0) !== p.sv) return expired();
    if (u.locked_until && Date.parse(u.locked_until) > Date.now())
        return scf.reply(msg, 423, { error: "บัญชีถูกล็อกชั่วคราวเพราะใส่รหัสผิดหลายครั้ง ลองใหม่หลัง " +
            new Date(u.locked_until).toLocaleTimeString("th-TH", { hour: "2-digit", minute: "2-digit" }) + " น." });
    if (u.role !== "admin") {
        const farm = (global.get("farms") || []).find(f => f.id === u.farm_id);
        if (!farm || !farm.active) return expired();
    }
    const secret = scf.openSecret(u.totp_secret);
    if (!secret) return expired();
    const code = String(b.code || "").trim();
    let step = null, backupLeft = null;
    if (/^[0-9\s]{6,7}$/.test(code)) step = scf.verifyTotp(secret, code, u.totp_enabled ? u.totp_last_step : null);
    else if (u.totp_enabled && Array.isArray(u.mfa_backup) && u.mfa_backup.includes(scf.hashBackup(code))) {
        backupLeft = u.mfa_backup.filter(h => h !== scf.hashBackup(code));
    }
    if (step === null && backupLeft === null) {
        const n = (u.failed_logins || 0) + 1, lock = n >= 5;
        await scf.db.update("users", "id=eq." + u.id, { failed_logins: lock ? 0 : n, locked_until: lock ? new Date(Date.now() + 5 * 60000).toISOString() : null });
        rec.n++; flow.set(ipKey, rec);
        await audit("login_fail", u, { reason: lock ? "mfa_locked_now" : "mfa", ip });
        return scf.reply(msg, lock ? 423 : 401, { error: lock ? "ใส่รหัสผิด 5 ครั้ง บัญชีถูกล็อก 5 นาที" : "รหัสยืนยันไม่ถูกต้อง (ดูรหัสล่าสุดในแอป แล้วลองใหม่)", code: "mfa" });
    }
    const patch = { failed_logins: 0, locked_until: null, last_login: new Date().toISOString() };
    if (step !== null) patch.totp_last_step = step;
    if (backupLeft) patch.mfa_backup = backupLeft;
    let backupCodes;
    const setup = !u.totp_enabled;
    if (setup) { const bc = scf.newBackupCodes(); patch.totp_enabled = true; patch.mfa_backup = bc.hashes; backupCodes = bc.codes; }
    await scf.db.update("users", "id=eq." + u.id, patch);
    const all = global.get("users") || {};
    if (all[u.id]) { all[u.id].totp_enabled = true; global.set("users", all); }
    await audit("login_ok", u, { ip, mfa: backupLeft ? "backup" : "totp", mfa_setup: setup || undefined });
    rec.n = 0; flow.set(ipKey, rec);
    const view = Object.assign({}, u, { totp_enabled: true, coop_ids: (all[u.id] || {}).coop_ids || [] });
    return scf.reply(msg, 200, { token: scf.signToken(u), expires_in: scf.TOKEN_TTL,
        user: Object.assign(scf.publicUser(view), { perms: scf.permsOf(view) }),
        backup_codes: backupCodes, backup_left: backupLeft ? backupLeft.length : undefined });
} catch (e) {
    node.error("mfa: " + e.message);
    return scf.errorReply(msg, e);
}
